/* 개역개정 보충 본문 — 1권 (개역한글 색인에 없는 구절) */
window.KRV_X={"6:8":[[5,"나와 나를 따르는 모든 백성은 다 성읍으로 가까이 가리니 그들이 처음과 같이 우리에게로 쳐 올라올 것이라 그리 할 때에 우리가 그들 앞에서 도망하면"],[31,"이는 여호와의 종 모세가 이스라엘 자손에게 명령한 것과 모세의 율법책에 기록된 대로 쇠 연장으로 다듬지 아니한 새 돌로 만든 제단이라 무리가 여호와께 번제물과 화목제물을 그 위에 드렸으며"],[32,"여호수아가 거기서 모세가 기록한 율법을 이스라엘 자손의 목전에서 그 돌에 기록하매"]],"12:14":[[6,"왕을 죽인 자의 자녀들은 죽이지 아니하였으니 이는 모세의 율법책에 기록된 대로 함이라 곧 여호와께서 명령하여 이르시기를 자녀로 말미암아 아버지를 죽이지 말 것이요 아버지로 말미암아 자녀를 죽이지 말 것이라 오직 사람마다 자기의 죄로 말미암아 죽을 것이니라 하셨더라"],[8,"아마샤가 예후의 손자 여호아하스의 아들 이스라엘의 왕 요아스에게 사자를 보내 이르되 오라 우리가 서로 대면하자 한지라"]],"16:8":[[1,"이스라엘 자손이 자기들의 성읍에 거주하였더니 일곱째 달에 이르러 모든 백성이 일제히 수문 앞 광장에 모여 학사 에스라에게 여호와께서 이스라엘에게 명령하신 모세의 율법책을 가져오기를 청하매"],[9,"백성이 율법의 말씀을 듣고 다 우는지라 총독 느헤미야와 제사장 겸 학사 에스라와 백성을 가르치는 레위 사람들이 모든 백성에게 이르기를 오늘은 너희 하나님 여호와의 성일이니 슬퍼하지 말며 울지 말라 하고"],[13,"그 이튿날 뭇 백성의 족장들과 제사장들과 레위 사람들이 율법의 말씀을 밝히 알고자 하여 학사 에스라에게 모여서"],[14,"율법에 기록된 바를 본즉 여호와께서 모세를 통하여 명령하시기를 이스라엘 자손은 일곱째 달 절기에 초막에서 거할지니라 하였고"],[15,"또 일렀으되 모든 성읍과 예루살렘에 공포하여 이르기를 너희는 산에 가서 감람나무 가지와 들감람나무 가지와 화석류나무 가지와 종려나무 가지와 기타 무성한 나무 가지를 가져다가 기록한 바를 따라 초막을 지으라 하라 한지라"],[16,"백성이 이에 나가서 나뭇가지를 가져다가 혹은 지붕 위에, 혹은 뜰 안에, 혹은 하나님의 전 뜰에, 혹은 수문 광장에, 혹은 에브라임 문 광장에 초막을 짓되"],[17,"사로잡혔다가 돌아온 회중이 다 초막을 짓고 그 안에서 거하니 눈의 아들 여호수아 때로부터 그 날까지 이스라엘 자손이 이같이 행한 일이 없었으므로 이에 크게 기뻐하며"],[18,"에스라는 첫날부터 끝날까지 날마다 하나님의 율법책을 낭독하고 무리가 이레 동안 절기를 지키고 여덟째 날에 규례를 따라 성회를 열었느니라"]],"23:65":[[17,"보라 내가 새 하늘과 새 땅을 창조하나니 이전 것은 기억되거나 마음에 생각나지 아니할 것이라"]],"19:121":[[1,"내가 산을 향하여 눈을 들리라 나의 도움이 어디서 올까"],[2,"나의 도움은 천지를 지으신 여호와에게서로다"],[3,"여호와께서 너를 실족하지 아니하게 하시며 너를 지키시는 이가 졸지 아니하시리로다"],[4,"이스라엘을 지키시는 이는 졸지도 아니하시고 주무시지도 아니하시리로다"],[5,"여호와는 너를 지키시는 이시라 여호와께서 네 오른쪽에서 네 그늘이 되시나니"],[6,"낮의 해가 너를 상하게 하지 아니하며 밤의 달도 너를 해치지 아니하리로다"],[7,"여호와께서 너를 지켜 모든 환난을 면하게 하시며 또 네 영혼을 지키시리로다"],[8,"여호와께서 너의 출입을 지금부터 영원까지 지키시리로다"]],"10:24":[[13,"갓이 다윗에게 이르러 아뢰어 이르되 왕의 땅에 칠 년 기근이 있을 것이니이까 혹은 왕이 왕의 원수에게 쫓겨 석 달 동안 그들 앞에서 도망하실 것이니이까 혹은 왕의 땅에 사흘 동안 전염병이 있을 것이니이까 왕은 생각하여 보고 나를 보내신 이에게 무엇을 대답하게 하소서 하는지라"],[24,"왕이 아라우나에게 이르되 그렇지 아니하다 내가 값을 주고 네게서 사리라 값 없이는 내 하나님 여호와께 번제를 드리지 아니하리라 하고 다윗이 은 오십 세겔로 타작 마당과 소를 사고"]],"19:51":[[2,"나의 죄악을 말갛게 씻으시며 나의 죄를 깨끗이 제하소서"],[3,"무릇 나는 내 죄과를 아오니 내 죄가 항상 내 앞에 있나이다"],[4,"내가 주께만 범죄하여 주의 목전에 악을 행하였사오니 주께서 말씀하실 때에 의로우시다 하고 주께서 심판하실 때에 순전하시다 하리이다"],[5,"내가 죄악 중에서 출생하였음이여 어머니가 죄 중에서 나를 잉태하였나이다"],[6,"보소서 주께서는 중심이 진실함을 원하시오니 내게 지혜를 은밀히 가르치시리이다"],[7,"우슬초로 나를 정결하게 하소서 내가 정하리이다 나의 죄를 씻어 주소서 내가 눈보다 희리이다"],[17,"하나님께서 구하시는 제사는 상한 심령이라 하나님이여 상하고 통회하는 마음을 주께서 멸시하지 아니하시리이다"]],"24:17":[[2,"그들의 자녀가 높은 언덕 위 푸른 나무 곁에 있는 그 제단들과 아세라들을 생각하도다"],[9,"만물보다 거짓되고 심히 부패한 것은 마음이라 누가 능히 이를 알리요마는"],[10,"나 여호와는 심장을 살피며 폐부를 시험하고 각각 그의 행위와 그의 행실대로 보응하나니"]],"10:19":[[2,"왕이 그 아들을 위하여 슬퍼한다 함이 그 날에 백성들에게 들리매 그 날의 승리가 모든 백성에게 슬픔이 된지라"],[24,"사울의 손자 므비보셋이 내려와 왕을 맞으니 그는 왕이 떠난 날부터 평안히 돌아오는 날까지 그의 발을 맵시 내지 아니하며 그의 수염을 깎지 아니하며 옷을 빨지 아니하였더라"],[43,"이스라엘 사람이 유다 사람에게 대답하여 이르되 우리는 왕에 대하여 열 몫을 가졌으니 다윗에게 대하여 너희보다 더욱 관계가 있거늘 너희가 어찌 우리를 멸시하여 우리 왕을 모셔 오는 일에 먼저 우리와 의논하지 아니하였느냐 하나 유다 사람의 말이 이스라엘 사람의 말보다 더 강경하였더라"]],"35:3":[[2,"여호와여 내가 주께 대한 소문을 듣고 놀랐나이다 여호와여 주는 주의 일을 이 수년 내에 부흥하게 하옵소서 이 수년 내에 나타내시옵소서 진노 중에라도 긍휼을 잊지 마옵소서"]],"7:9":[[13,"포도나무가 그들에게 이르되 하나님과 사람을 기쁘게 하는 내 포도주를 내가 어찌 버리고 가서 나무들 위에 우쭐대리요 한지라"]],"19:104":[[15,"사람의 마음을 기쁘게 하는 포도주와 사람의 얼굴을 윤택하게 하는 기름과 사람의 마음을 힘있게 하는 양식을 주셨도다"]],"20:31":[[6,"독주는 죽게 된 자에게, 포도주는 마음에 근심하는 자에게 줄지어다"],[10,"누가 현숙한 여인을 찾아 얻겠느냐 그의 값은 진주보다 더 하니라"]],"23:21":[[9,"보소서 마병대가 쌍쌍이 오나이다 하니 그가 대답하여 이르시되 함락되었도다 함락되었도다 바벨론이여 그들이 조각한 신상들이 다 부서져 땅에 떨어졌도다 하시도다"]],"19:34":[[9,"너희 성도들아 여호와를 경외하라 그를 경외하는 자에게는 부족함이 없도다"],[15,"여호와의 눈은 의인을 향하시고 그의 귀는 그들의 부르짖음에 기울이시는도다"],[18,"여호와는 마음이 상한 자를 가까이 하시고 충심으로 통회하는 자를 구원하시는도다"]],"24:14":[[11,"여호와께서 또 내게 이르시되 너는 이 백성을 위하여 복을 구하지 말라"]],"19:91":[[1,"지존자의 은밀한 곳에 거주하며 전능자의 그늘 아래에 사는 자여,"],[11,"그가 너를 위하여 그의 천사들을 명령하사 네 모든 길에서 너를 지키게 하심이라"]],"19:78":[[6,"이는 그들로 후대 곧 태어날 자손에게 이를 알게 하고 그들은 일어나 그들의 자손에게 일러서"],[34,"하나님이 그들을 죽이실 때에 그들이 그에게 구하며 돌이켜 하나님을 간절히 찾았고"],[35,"하나님이 그들의 반석이시며 지존하신 하나님이 그들의 구속자이심을 기억하였도다"],[36,"그러나 그들이 입으로 그에게 아첨하며 자기 혀로 그에게 거짓을 말하였으니"],[37,"이는 하나님께 향하는 그들의 마음이 정함이 없으며 그의 언약에 성실하지 아니하였음이로다"],[38,"오직 하나님은 긍휼하시므로 죄악을 덮어 주시어 멸망시키지 아니하시고 그의 진노를 여러 번 돌이키시며 그의 모든 분을 다 쏟아 내지 아니하셨으니"],[40,"그들이 광야에서 그에게 반항하며 사막에서 그를 슬프시게 함이 몇 번인가"],[49,"그의 맹렬한 노여움과 진노와 분노와 고난 곧 재앙의 천사들을 그들에게 내려보내셨으며"]],"27:10":[[12,"그가 내게 이르되 다니엘아 두려워하지 말라 네가 깨달으려 하여 네 하나님 앞에 스스로 겸비하게 하기로 결심하던 첫날부터 네 말이 응답 받았으므로 내가 네 말로 말미암아 왔느니라"]],"23:41":[[6,"각기 이웃을 도우며 그 형제에게 이르기를 너는 힘을 내라 하고"],[10,"두려워하지 말라 내가 너와 함께 함이라 놀라지 말라 나는 네 하나님이 됨이라 내가 너를 굳세게 하리라 참으로 너를 도와 주리라 참으로 나의 의로운 오른손으로 너를 붙들리라"],[12,"네가 찾아도 너와 싸우던 자들을 만나지 못할 것이요 너를 치는 자들은 아무것도 아닌 것 같고 허무한 것 같이 되리니"]],"14:3":[[1,"솔로몬이 예루살렘 모리아 산에 여호와의 전 건축하기를 시작하니 그 곳은 전에 여호와께서 그의 아버지 다윗에게 나타나신 곳이요 여부스 사람 오르난의 타작 마당에 다윗이 정한 곳이라"]],"19:25":[[9,"온유한 자를 정의로 지도하심이여 온유한 자에게 그의 도를 가르치시리로다"],[13,"그의 영혼은 평안히 살고 그의 자손은 땅을 상속하리로다"]],"9:1":[[11,"서원하여 이르되 만군의 여호와여 만일 주의 여종의 고통을 돌보시고 나를 기억하사 주의 여종을 잊지 아니하시고 주의 여종에게 아들을 주시면 내가 그의 평생에 그를 여호와께 드리고 삭도를 그의 머리에 대지 아니하겠나이다"]],"21:5":[[2,"너는 하나님 앞에서 함부로 입을 열지 말며 급한 마음으로 말을 내지 말라 하나님은 하늘에 계시고 너는 땅에 있음이니라 그런즉 마땅히 말을 적게 할 것이라"],[4,"네가 하나님께 서원하였거든 갚기를 더디게 하지 말라 하나님은 우매한 자들을 기뻐하지 아니하시나니 서원한 것을 갚으라"],[5,"서원하고 갚지 아니하는 것보다 서원하지 아니하는 것이 더 나으니"],[6,"네 입으로 네 육체가 범죄하게 하지 말라 천사 앞에서 내가 서원한 것이 실수라고 말하지 말라 어찌 하나님께서 네 목소리로 말미암아 진노하사 네 손으로 한 것을 멸하시게 하랴"]],"12:10":[[10,"그런즉 이제 너희는 알라 곧 여호와께서 아합의 집에 대하여 하신 말씀은 하나도 땅에 떨어지지 아니하리라 여호와께서 그의 종 엘리야를 통하여 하신 말씀을 이제 이루셨도다 하니라"],[11,"예후가 아합의 집에 속한 이스르엘에 남아 있는 자를 다 죽이고 또 그의 귀족들과 신뢰 받는 자들과 제사장들을 죽이되 그에게 속한 자를 하나도 생존자를 남기지 아니하였더라"],[12,"예후가 일어나서 사마리아로 가더니 도중에 목자가 양털 깎는 집에 이르러"],[13,"예후가 유다의 왕 아하시야의 형제들을 만나 묻되 너희는 누구냐 하니 대답하되 우리는 아하시야의 형제라 이제 왕자들과 태후의 아들들에게 문안하러 내려가노라 하는지라"],[14,"이르되 사로잡으라 하매 곧 사로잡아 목자가 양털 깎는 집 웅덩이 곁에서 죽이니 사십이 명이 하나도 남지 아니하였더라"]],"19:3":[[3,"여호와여 주는 나의 방패시요 나의 영광이시요 나의 머리를 드시는 자이시니이다"]],"20:21":[[4,"눈이 높은 것과 마음이 교만한 것과 악인이 형통한 것은 다 죄니라"],[13,"귀를 막고 가난한 자가 부르짖는 소리를 듣지 아니하면 자기가 부르짖을 때에도 들을 자가 없으리라"]],"19:39":[[12,"여호와여 나의 기도를 들으시며 나의 부르짖음에 귀를 기울이소서 내가 눈물 흘릴 때에 잠잠하지 마옵소서 나는 주와 함께 있는 나그네이며 나의 모든 조상들처럼 떠도나이다"]],"23:52":[[4,"주 여호와께서 이와 같이 말씀하시되 내 백성이 전에 애굽에 내려가서 거기에 거류하였고 앗수르인은 공연히 그들을 압박하였도다"],[12,"여호와께서 너희 앞에서 행하시며 이스라엘의 하나님이 너희 뒤에서 호위하시리니 너희가 황급히 나오지 아니하며 도망하듯 다니지 아니하리라"]],"49:3":[[12,"우리가 그 안에서 그를 믿음으로 말미암아 담대함과 확신을 가지고 하나님께 나아감을 얻느니라"],[16,"그의 영광의 풍성함을 따라 그의 성령으로 말미암아 너희 속사람을 능력으로 강건하게 하시오며"],[17,"믿음으로 말미암아 그리스도께서 너희 마음에 계시게 하시옵고 너희가 사랑 가운데서 뿌리가 박히고 터가 굳어져서"],[18,"능히 모든 성도와 함께 지식에 넘치는 그리스도의 사랑을 알고"],[19,"그 너비와 길이와 높이와 깊이가 어떠함을 깨달아 하나님의 모든 충만하신 것으로 너희에게 충만하게 하시기를 구하노라"],[20,"우리 가운데서 역사하시는 능력대로 우리가 구하거나 생각하는 모든 것에 더 넘치도록 능히 하실 이에게"]],"6:3":[[4,"그러나 너희와 그 사이 거리가 이천 규빗쯤 되게 하고 그것에 가까이 하지는 말라 그리하면 너희가 행할 길을 알리니 너희가 이전에 이 길을 지나보지 못하였음이니라 하니라"]],"12:19":[[15,"그 앞에서 히스기야가 기도하여 이르되 그룹들 위에 계신 이스라엘의 하나님 여호와여 주는 천하 만국에 홀로 하나님이시라 주께서 천지를 만드셨나이다"],[25,"네가 듣지 못하였느냐 이 일은 내가 태초부터 행하였고 옛날부터 정한 바라 이제 내가 이루어 너로 견고한 성들을 멸하여 무너진 돌무더기가 되게 함이니라"]],"8:3":[[2,"네가 함께 하던 하녀들을 둔 보아스는 우리의 친족이 아니냐 보라 그가 오늘 밤에 타작 마당에서 보리를 까불리라"]],"7:19":[[4,"그의 장인 곧 그 여자의 아버지가 그를 머물게 하매 그가 삼 일 동안 그와 함께 머물며 먹고 마시며 거기서 유숙하다가"]],"8:2":[[5,"보아스가 베는 자들을 거느린 사환에게 이르되 이는 누구의 소녀냐 하니"],[14,"식사할 때에 보아스가 룻에게 이르되 이리로 와서 떡을 먹으며 네 떡 조각을 초에 찍으라 하므로 룻이 곡식 베는 자 곁에 앉으니 그가 볶은 곡식을 주매 룻이 배불리 먹고 남았더라"]],"20:9":[[3,"자기의 여종을 보내어 성중 높은 곳에서 불러 이르기를"],[10,"여호와를 경외하는 것이 지혜의 근본이요 거룩하신 자를 아는 것이 명철이니라"]],"10:4":[[9,"다윗이 브에롯 사람 림몬의 아들 레갑과 그의 형제 바아나에게 대답하여 그들에게 이르되 내 생명을 여러 환난 가운데서 건지신 여호와께서 살아 계심을 두고 맹세하노니"]],"19:9":[[9,"여호와는 압제를 당하는 자의 요새이시요 환난 때의 요새이시로다"]],"19:50":[[8,"나는 네 제물 때문에 너를 책망하지는 아니하리니 네 번제가 항상 내 앞에 있음이로다"],[9,"내가 네 집에서 수소나 네 우리에서 숫염소를 가져가지 아니하리니"],[10,"이는 삼림의 짐승들과 뭇 산의 가축이 다 내 것이며"],[11,"산의 모든 새들도 내가 아는 것이며 들의 짐승도 내 것임이로다"],[12,"내가 가령 주려도 네게 이르지 아니할 것은 세계와 거기에 충만한 것이 내 것임이로다"],[13,"내가 수소의 고기를 먹으며 염소의 피를 마시겠느냐"],[14,"감사로 하나님께 제사를 드리며 지존하신 이에게 네 서원을 갚으며"],[15,"환난 날에 나를 부르라 내가 너를 건지리니 네가 나를 영화롭게 하리로다"]],"17:1":[[12,"그러나 왕후 와스디는 내시가 전하는 왕명을 따르기를 싫어하니 왕이 진노하여 마음속이 불 붙는 듯하더라"]],"19:65":[[2,"기도를 들으시는 주여 모든 육체가 주께 나아오리이다"]],"23:6":[[5,"그 때에 내가 말하되 화로다 나여 망하게 되었도다 나는 입술이 부정한 사람이요 나는 입술이 부정한 백성 중에 거주하면서 만군의 여호와이신 왕을 뵈었음이로다 하였더라"],[7,"그것을 내 입술에 대며 이르되 보라 이것이 네 입에 닿았으니 네 악이 제하여졌고 네 죄가 사하여졌느니라 하더라"],[8,"내가 또 주의 목소리를 들으니 주께서 이르시되 내가 누구를 보내며 누가 우리를 위하여 갈꼬 하시니 그 때에 내가 이르되 내가 여기 있나이다 나를 보내소서 하였더니"]],"7:6":[[15,"그러나 기드온이 그에게 대답하되 오 주여 내가 무엇으로 이스라엘을 구원하리이까 보소서 나의 집은 므낫세 중에 극히 약하고 나는 내 아버지 집에서 가장 작은 자니이다 하니"],[19,"기드온이 가서 염소 새끼 하나를 준비하고 가루 한 에바로 무교병을 만들고 고기를 소쿠리에 담고 국을 양푼에 담아 상수리나무 아래 그에게로 가져다가 드리매"]],"11:3":[[5,"기브온에서 밤에 여호와께서 솔로몬의 꿈에 나타나시니라 하나님이 이르시되 내가 네게 무엇을 줄꼬 너는 구하라"],[7,"나의 하나님 여호와여 주께서 종으로 종의 아버지 다윗을 대신하여 왕이 되게 하셨사오나 종은 작은 아이라 출입할 줄을 알지 못하고"],[8,"왕께서 택하신 백성 가운데 있나이다 그들은 큰 백성이라 수효가 많아서 셀 수도 없고 기록할 수도 없사오니"],[9,"누가 주의 이 많은 백성을 재판할 수 있사오리이까 듣는 마음을 종에게 주사 주의 백성을 재판하여 선악을 분별하게 하옵소서"],[10,"솔로몬이 이것을 구하매 그 말씀이 주의 마음에 든지라"],[11,"이에 하나님이 그에게 이르시되 네가 이것을 구하도다 자기를 위하여 장수하기를 구하지 아니하며 부도 구하지 아니하며 자기 원수의 생명을 멸하기도 구하지 아니하고 오직 송사를 듣고 분별하는 지혜를 구하였으니"],[12,"내가 네 말대로 하여 네게 지혜롭고 총명한 마음을 주노니 네 앞에도 너와 같은 자가 없었거니와 네 뒤에도 너와 같은 자가 일어남이 없으리라"]],"24:1":[[6,"내가 이르되 슬프도소이다 주 여호와여 보소서 나는 아이라 말할 줄을 알지 못하나이다 하니"],[11,"여호와의 말씀이 또 내게 임하니라 이르시되 예레미야야 네가 무엇을 보느냐 하시매 내가 대답하되 내가 살구나무 가지를 보나이다"]],"41:4":[[15,"말씀이 길 가에 뿌려졌다는 것은 이들을 가리킴이니 곧 말씀을 들었을 때에 사탄이 즉시 와서 그들에게 뿌려진 말씀을 빼앗는 것이요"]],"19:107":[[4,"그들이 광야 사막 길에서 방황하며 거주할 성읍을 찾지 못하고"],[5,"주리고 목이 말라 그들의 영혼이 그들 안에서 피곤하였도다"],[6,"이에 그들이 근심 중에 여호와께 부르짖으매 그들의 고통에서 건지시고"],[7,"또 바른 길로 인도하사 거주할 성읍에 이르게 하셨도다"],[8,"여호와의 인자하심과 인생에게 행하신 기적으로 말미암아 그를 찬송할지로다"],[9,"그가 사모하는 영혼에게 만족을 주시며 주린 영혼에게 좋은 것으로 채워주심이로다"]],"26:9":[[1,"또 그가 큰 소리로 내 귀에 외쳐 이르시되 이 성읍을 관할하는 자들이 각기 죽이는 무기를 손에 들고 나아오게 하라 하시더라"],[4,"여호와께서 이르시되 너는 예루살렘 성읍 중에 순행하여 그 가운데에서 행하는 모든 가증한 일로 말미암아 탄식하며 우는 자의 이마에 표를 그리라"]],"7:18":[[23,"단 자손을 부르는지라 그들이 얼굴을 돌려 미가에게 이르되 네가 무슨 일로 이같이 모아 가지고 왔느냐 하니"]],"6:7":[[1,"이스라엘 자손들이 온전히 바친 물건으로 말미암아 범죄하였으니 이는 유다 지파 세라의 증손 삽디의 손자 갈미의 아들 아간이 온전히 바친 물건을 가졌음이라 여호와께서 이스라엘 자손들에게 진노하시니라"],[2,"여호수아가 여리고에서 사람을 벧엘 동쪽 벧아웬 곁에 있는 아이로 보내며 그들에게 말하여 이르되 올라가서 그 땅을 정탐하라 하매 그 사람들이 올라가서 아이를 정탐하고"],[3,"여호수아에게로 돌아와 그에게 이르되 백성을 다 올라가게 하지 말고 이삼천 명만 올라가서 아이를 치게 하소서 그들은 소수이니 모든 백성을 그리로 보내어 수고롭게 하지 마소서 하므로"],[4,"백성 중 삼천 명쯤 그리로 올라갔다가 아이 사람 앞에서 도망하니"],[5,"아이 사람이 그들을 삼십육 명쯤 쳐죽이고 성문 앞에서부터 스바림까지 쫓아가 내려가는 비탈에서 쳤으므로 백성의 마음이 녹아 물 같이 된지라"],[6,"여호수아가 옷을 찢고 이스라엘 장로들과 함께 여호와의 궤 앞에서 땅에 엎드려 머리에 티끌을 뒤집어쓰고 저물도록 있다가"],[7,"이르되 슬프도소이다 주 여호와여 어찌하여 이 백성을 인도하여 요단을 건너게 하시고 우리를 아모리 사람의 손에 넘겨 멸망시키려 하셨나이까 우리가 요단 저쪽을 만족하게 여겨 거주하였더면 좋을 뻔하였나이다"],[8,"주여 이스라엘이 그의 원수들 앞에서 돌아섰으니 내가 무슨 말을 하오리이까"],[9,"가나안 사람과 이 땅의 모든 사람들이 듣고 우리를 둘러싸고 우리 이름을 세상에서 끊으리니 주의 크신 이름을 위하여 어떻게 하시려 하나이까 하니"],[10,"여호와께서 여호수아에게 이르시되 일어나라 어찌하여 이렇게 엎드렸느냐"],[11,"이스라엘이 범죄하여 내가 그들에게 명령한 나의 언약을 어겼으며 또한 그들이 온전히 바친 물건을 가져가고 도둑질하며 속이고 그것을 그들의 물건들 가운데에 두었느니라"],[12,"그러므로 이스라엘 자손들이 그들의 원수 앞에 능히 맞서지 못하고 그 앞에서 돌아섰나니 이는 그들도 온전히 바친 것이 됨이라 그 온전히 바친 물건을 너희 중에서 멸하지 아니하면 내가 다시는 너희와 함께 있지 아니하리라"],[13,"너는 일어나서 백성을 거룩하게 하여 이르기를 너희는 내일을 위하여 스스로 거룩하게 하라 이스라엘의 하나님 여호와의 말씀에 이스라엘아 너희 가운데에 온전히 바친 물건이 있나니 너희가 그 온전히 바친 물건을 너희 가운데에서 제하기까지는 네 원수들 앞에 능히 맞서지 못하리라"],[14,"너희는 아침에 너희의 지파대로 가까이 나아오라 여호와께 뽑히는 그 지파는 그 족속대로 가까이 나아올 것이요 여호와께 뽑히는 족속은 그 가족대로 가까이 나아올 것이요 여호와께 뽑히는 그 가족은 그 남자들이 가까이 나아올 것이며"],[15,"온전히 바친 물건을 가진 자로 뽑힌 자를 불사르되 그와 그의 모든 소유를 그리하라 이는 여호와의 언약을 어기고 이스라엘 가운데에서 망령된 일을 행하였음이라 하셨다 하라"]],"23:63":[[1,"에돔에서 오는 이 누구며 붉은 옷을 입고 보스라에서 오는 이 누구냐 그의 화려한 의복 큰 능력으로 걷는 이가 누구냐 그는 나이니 공의를 말하는 이요 구원하는 능력을 가진 이니라"],[2,"어찌하여 네 의복이 붉으며 네 옷이 포도즙틀을 밟는 자 같으냐"],[3,"만민 가운데 나와 함께 한 자가 없이 내가 홀로 포도즙틀을 밟았는데 내가 노함으로 말미암아 무리를 밟았고 분함으로 말미암아 짓밟았으므로 그들의 선혈이 내 옷에 튀어 내 의복을 다 더럽혔음이니"],[4,"이는 내 원수 갚는 날이 내 마음에 있고 내가 구속할 해가 왔으나"],[5,"내가 본즉 도와 주는 자도 없고 붙들어 주는 자도 없으므로 이상하게 여겨 내 팔이 나를 구원하며 내 분이 나를 붙들었음이라"],[6,"내가 노함으로 말미암아 만민을 밟았으며 내가 분함으로 말미암아 그들을 취하게 하고 그들의 선혈이 땅에 쏟아지게 하였느니라"],[7,"내가 여호와께서 우리에게 베푸신 모든 자비와 그의 찬송을 말하며 그의 사랑을 따라, 그의 많은 자비를 따라 이스라엘 집에 베푸신 큰 은총을 말하리라"],[8,"그가 말씀하시되 그들은 실로 나의 백성이요 거짓을 행하지 아니하는 자녀라 하시고 그들의 구원자가 되사"],[9,"그들의 모든 환난에 동참하사 자기 앞의 사자로 하여금 그들을 구원하시며 그의 사랑과 그의 자비로 그들을 구원하시고 옛적 모든 날에 그들을 드시며 안으셨으나"],[10,"그들이 반역하여 주의 성령을 근심하게 하였으므로 그가 돌이켜 그들의 대적이 되사 친히 그들을 치셨더니"],[11,"백성이 옛적 모세의 때를 기억하여 이르되 백성과 양 떼의 목자를 바다에서 올라오게 하신 이가 이제 어디 계시냐 그들 가운데에 성령을 두신 이가 이제 어디 계시냐"],[12,"그의 영광의 팔이 모세의 오른손을 이끄시며 그의 이름을 영원하게 하려 하사 그들 앞에서 물을 갈라지게 하시고"],[13,"그들을 깊음으로 인도하시되 광야에 있는 말 같이 넘어지지 않게 하신 이가 이제 어디 계시냐"],[14,"여호와의 영이 그들을 골짜기로 내려가는 가축 같이 편히 쉬게 하셨도다 주께서 이와 같이 주의 백성을 인도하사 이름을 영화롭게 하셨나이다 하였느니라"]],"27:3":[[13,"느부갓네살 왕이 노하고 분하여 사드락과 메삭과 아벳느고를 끌어오라 말하매 드디어 그 사람들을 왕의 앞으로 끌어온지라"],[14,"느부갓네살이 그들에게 물어 이르되 사드락, 메삭, 아벳느고야 너희가 내 신을 섬기지 아니하며 내가 세운 금 신상에게 절하지 아니한다 하니 사실이냐"],[15,"이제라도 너희가 준비하였다가 나팔과 피리와 수금과 삼현금과 양금과 생황과 및 모든 악기 소리를 들을 때 내가 만든 신상 앞에 엎드려 절하면 좋거니와 너희가 만일 절하지 아니하면 즉시 너희를 맹렬히 타는 풀무불 가운데에 던져 넣을 것이니 능히 너희를 내 손에서 건져낼 신이 누구이겠느냐 하니"],[16,"사드락과 메삭과 아벳느고가 왕에게 대답하여 이르되 느부갓네살이여 우리가 이 일에 대하여 왕에게 대답할 필요가 없나이다"],[17,"왕이여 우리가 섬기는 하나님이 계시다면 우리를 맹렬히 타는 풀무불 가운데에서 능히 건져내시겠고 왕의 손에서도 건져내시리이다"],[18,"그렇게 하지 아니하실지라도 왕이여 우리가 왕의 신들을 섬기지도 아니하고 왕이 세우신 금 신상에게 절하지도 아니할 줄을 아옵소서"]],"24:11":[[3,"그들에게 이르기를 이스라엘의 하나님 여호와께서 이와 같이 말씀하시되 이 언약의 말을 따르지 않는 자는 저주를 받을 것이니라"],[9,"여호와께서 또 내게 이르시되 유다인과 예루살렘 주민 중에 반역이 있도다"],[10,"그들이 내 말 듣기를 거절한 자기들의 선조의 죄악으로 돌아가서 다른 신들을 따라 섬겼은즉 이스라엘 집과 유다 집이 내가 그들의 조상들과 맺은 언약을 깨뜨렸도다"],[11,"그러므로 나 여호와가 이와 같이 말하노라 보라 내가 재앙을 그들에게 내리리니 그들이 피할 수 없을 것이라 그들이 내게 부르짖을지라도 내가 듣지 아니할 것인즉"]],"24:6":[[10,"내가 누구에게 말하며 누구에게 경책하여 듣게 할꼬 보라 그 귀가 할례를 받지 못하였으므로 듣지 못하는도다 보라 여호와의 말씀을 그들이 자신들에게 욕으로 여기고 이를 즐겨 하지 아니하니"],[19,"땅이여 들으라 내가 이 백성에게 재앙을 내리리니 이것이 그들의 생각의 결과라 그들이 내 말을 듣지 아니하며 내 율법을 거절하였음이니라"],[20,"시바에서 유향과 먼 곳에서 향품을 내게로 가져옴은 어찌함이냐 나는 그들의 번제를 받지 아니하며 그들의 희생제물을 달게 여기지 않노라"]],"12:6":[[18,"아람 사람이 엘리사에게 내려오매 엘리사가 여호와께 기도하여 이르되 원하건대 저 무리의 눈을 어둡게 하옵소서 하매 엘리사의 말대로 그들의 눈을 어둡게 하신지라"]],"9:2":[[1,"한나가 기도하여 이르되 내 마음이 여호와로 말미암아 즐거워하며 내 뿔이 여호와로 말미암아 높아졌으며 내 입이 내 원수들을 향하여 크게 열렸으니 이는 내가 주의 구원으로 말미암아 기뻐함이니이다"],[2,"여호와와 같이 거룩하신 이가 없으시니 이는 주 밖에 다른 이가 없고 우리 하나님 같은 반석도 없으심이니이다"],[3,"심히 교만한 말을 다시 하지 말 것이며 오만한 말을 너희의 입에서 내지 말지어다 여호와는 지식의 하나님이시라 행동을 달아 보시느니라"],[4,"용사의 활은 꺾이고 넘어진 자는 힘으로 띠를 띠도다"],[5,"풍족하던 자들은 양식을 위하여 품을 팔고 주리던 자들은 다시 주리지 아니하도다 전에 임신하지 못하던 자는 일곱을 낳았고 많은 자녀를 둔 자는 쇠약하도다"],[6,"여호와는 죽이기도 하시고 살리기도 하시며 스올에 내리게도 하시고 거기에서 올리기도 하시는도다"],[7,"여호와는 가난하게도 하시고 부하게도 하시며 낮추기도 하시고 높이기도 하시는도다"],[8,"가난한 자를 진토에서 일으키시며 빈궁한 자를 거름더미에서 올리사 귀족들과 함께 앉게 하시며 영광의 자리를 차지하게 하시는도다 땅의 기둥들은 여호와의 것이라 여호와께서 세계를 그것들 위에 세우셨도다"],[9,"그가 그의 거룩한 자들의 발을 지키실 것이요 악인들을 흑암 중에서 잠잠하게 하시리니 힘으로는 이길 사람이 없음이로다"],[10,"여호와를 대적하는 자는 산산이 깨어질 것이라 하늘에서 우레로 그들을 치시리로다 여호와께서 땅 끝까지 심판을 내리시고 자기 왕에게 힘을 주시며 자기의 기름 부음을 받은 자의 뿔을 높이시리로다 하니라"],[22,"엘리가 매우 늙었더니 그의 아들들이 온 이스라엘에게 행한 모든 일과 회막 문에서 수종 드는 여인들과 동침하였음을 듣고"]],"6:4":[[5,"그들에게 이르되 요단 가운데로 들어가 너희 하나님 여호와의 궤 앞으로 가서 이스라엘 자손들의 지파 수대로 각기 돌 한 개씩 가져다가 어깨에 메라"],[6,"이것이 너희 중에 표징이 되리라 후일에 너희의 자손들이 물어 이르되 이 돌들은 무슨 뜻이냐 하거든"],[22,"너희는 너희의 자손들에게 알게 하여 이르기를 이스라엘이 마른 땅을 밟고 이 요단을 건넜음이라"]],"29:1":[[4,"팥중이가 남긴 것을 메뚜기가 먹고 메뚜기가 남긴 것을 느치가 먹고 느치가 남긴 것을 황충이 먹었도다"],[5,"취하는 자들아 너희는 깨어 울지어다 포도주를 마시는 자들아 너희는 울지어다 이는 단 포도주가 너희 입에서 끊어졌음이니"],[6,"다른 한 민족이 내 땅에 올라왔음이로다 그들은 강하고 수가 많으며 그 이빨은 사자의 이빨 같고 그 어금니는 암사자의 어금니 같도다"],[7,"그들이 내 포도나무를 멸하며 내 무화과나무를 긁어 말갛게 벗겨서 버리니 그 모든 가지가 하얗게 되었도다"]],"19:103":[[1,"내 영혼아 여호와를 송축하라 내 속에 있는 것들아 다 그의 거룩한 이름을 송축하라"],[2,"내 영혼아 여호와를 송축하며 그의 모든 은택을 잊지 말지어다"],[3,"그가 네 모든 죄악을 사하시며 네 모든 병을 고치시며"],[4,"네 생명을 파멸에서 속량하시고 인자와 긍휼로 관을 씌우시며"],[5,"좋은 것으로 네 소원을 만족하게 하사 네 청춘을 독수리 같이 새롭게 하시는도다"],[6,"여호와께서 공의로운 일을 행하시며 억압 당하는 모든 자를 위하여 심판하시는도다"],[7,"그의 행위를 모세에게, 그의 행사를 이스라엘 자손에게 알리셨도다"],[8,"여호와는 긍휼이 많으시고 은혜로우시며 노하기를 더디 하시고 인자하심이 풍부하시도다"],[9,"자주 경책하지 아니하시며 노를 영원히 품지 아니하시리로다"],[10,"우리의 죄를 따라 우리를 처벌하지는 아니하시며 우리의 죄악을 따라 우리에게 그대로 갚지는 아니하셨으니"],[11,"이는 하늘이 땅에서 높음 같이 그를 경외하는 자에게 그의 인자하심이 크심이로다"],[12,"동이 서에서 먼 것 같이 우리의 죄과를 우리에게서 멀리 옮기셨으며"],[13,"아버지가 자식을 긍휼히 여김 같이 여호와께서는 자기를 경외하는 자를 긍휼히 여기시나니"],[14,"이는 그가 우리의 체질을 아시며 우리가 단지 먼지뿐임을 기억하심이로다"],[19,"여호와께서 그의 보좌를 하늘에 세우시고 그의 왕권으로 만유를 다스리시도다"],[21,"그에게 수종들며 그의 뜻을 행하는 모든 천군이여 여호와를 송축하라"]],"26:18":[[4,"모든 영혼이 다 내게 속한지라 아버지의 영혼이 내게 속함 같이 그의 아들의 영혼도 내게 속하였나니 범죄하는 그 영혼은 죽으리라"],[23,"주 여호와의 말씀이니라 내가 어찌 악인이 죽는 것을 조금인들 기뻐하랴 그가 돌이켜 그 길에서 떠나 사는 것을 어찌 기뻐하지 아니하겠느냐"]],"23:53":[[2,"그는 주 앞에서 자라나기를 연한 순 같고 마른 땅에서 나온 뿌리 같아서 고운 모양도 없고 풍채도 없은즉 우리가 보기에 흠모할 만한 아름다운 것이 없도다"],[6,"우리는 다 양 같아서 그릇 행하여 각기 제 길로 갔거늘 여호와께서는 우리 모두의 죄악을 그에게 담당시키셨도다"],[7,"그가 곤욕을 당하여 괴로울 때에도 그의 입을 열지 아니하였음이여 마치 도수장으로 끌려 가는 어린 양과 털 깎는 자 앞에서 잠잠한 양 같이 그의 입을 열지 아니하였도다"],[10,"여호와께서 그에게 상함을 받게 하시기를 원하사 질고를 당하게 하셨은즉 그의 영혼을 속건제물로 드리기에 이르면 그가 씨를 보게 되며 그의 날은 길 것이요 또 그의 손으로 여호와께서 기뻐하시는 뜻을 성취하리로다"]],"16:2":[[1,"아닥사스다 왕 제이십년 니산월에 왕 앞에 포도주가 있기로 내가 그 포도주를 왕에게 드렸는데 이전에는 내가 왕 앞에서 수심이 없었더니"]],"17:3":[[7,"아하수에로 왕 제십이년 첫째 달 곧 니산월에 무리가 하만 앞에서 날과 달에 대하여 부르 곧 제비를 뽑아 열두째 달 곧 아달월을 얻은지라"]],"26:45":[[15,"또 이스라엘의 윤택한 초장의 가축 떼 이백 마리에서는 어린 양 한 마리를 드릴 것이라 백성을 속죄하기 위하여 이것들을 소제와 번제와 감사 제물로 삼을지니라 주 여호와의 말씀이니라"],[18,"여호와께서 이같이 말씀하셨느니라 첫째 달 초하룻날에 흠 없는 수송아지 한 마리를 가져다가 성소를 정결하게 하되"],[19,"제사장이 그 속죄제 희생제물의 피를 가져다가 성전 문설주와 제단 아래층 네 모퉁이와 안뜰 문설주에 바를 것이요"],[20,"그 달 칠일에도 모든 과실범과 모르고 범죄한 자를 위하여 역시 그렇게 하여 성전을 속죄할지니라"]],"23:30":[[18,"그러나 여호와께서 기다리시나니 이는 너희에게 은혜를 베풀려 하심이요 일어나시리니 이는 너희를 긍휼히 여기려 하심이라 대저 여호와는 정의의 하나님이심이라 그를 기다리는 자마다 복이 있도다"],[29,"너희가 거룩한 절기를 지키는 밤에 하듯이 노래할 것이며 피리를 불며 여호와의 산으로 가서 이스라엘의 반석에게로 나아가는 자 같이 마음에 즐거워할 것이라"]],"19:46":[[7,"만군의 여호와께서 우리와 함께 하시니 야곱의 하나님은 우리의 피난처시로다 (셀라)"],[10,"이르시기를 너희는 가만히 있어 내가 하나님 됨을 알지어다 내가 뭇 나라 중에서 높임을 받으리라 내가 세계 중에서 높임을 받으리라 하시도다"]],"19:96":[[1,"새 노래로 여호와께 노래하라 온 땅이여 여호와께 노래할지어다"],[2,"여호와께 노래하여 그의 이름을 송축하며 그의 구원을 날마다 전파할지어다"],[3,"그의 영광을 백성들 가운데에, 그의 기이한 행적을 만민 가운데에 선포할지어다"],[4,"여호와는 위대하시니 지극히 찬양할 것이요 모든 신들보다 경외할 것임이여"],[5,"만국의 모든 신들은 우상들이지만 여호와께서는 하늘을 지으셨음이로다"],[6,"존귀와 위엄이 그의 앞에 있으며 능력과 아름다움이 그의 성소에 있도다"],[7,"만국의 족속들아 영광과 권능을 여호와께 돌릴지어다 여호와께 돌릴지어다"],[8,"여호와의 이름에 합당한 영광을 그에게 돌릴지어다 예물을 들고 그의 궁정에 들어갈지어다"]],"19:30":[[11,"주께서 나의 슬픔이 변하여 내게 춤이 되게 하시며 나의 베옷을 벗기고 기쁨으로 띠 띠우셨나이다"]],"9:25":[[11,"내가 어찌 내 떡과 물과 내 양 털 깎는 자를 위하여 잡은 고기를 가져다가 어디서 왔는지도 알지 못하는 자들에게 주겠느냐 한지라"]],"19:37":[[11,"그러나 온유한 자들은 땅을 차지하며 풍성한 화평으로 즐거워하리로다"],[14,"악인이 칼을 빼고 활을 당겨 가난하고 궁핍한 자를 엎드러뜨리며 행위가 정직한 자를 죽이고자 하나"],[31,"그의 마음에는 하나님의 법이 있으니 그의 걸음은 실족함이 없으리로다"]],"23:55":[[1,"오호라 너희 모든 목마른 자들아 물로 나아오라 돈 없는 자도 오라 너희는 와서 사 먹되 돈 없이, 값 없이 와서 포도주와 젖을 사라"],[2,"너희가 어찌하여 양식이 아닌 것을 위하여 은을 달아 주며 배부르게 하지 못할 것을 위하여 수고하느냐 내게 듣고 들을지어다 그리하면 너희가 좋은 것을 먹을 것이며 너희 자신들이 기름진 것으로 즐거움을 얻으리라"],[7,"악인은 그의 길을, 불의한 자는 그의 생각을 버리고 여호와께로 돌아오라 그리하면 그가 긍휼히 여기시리라 우리 하나님께로 돌아오라 그가 너그럽게 용서하시리라"],[10,"이는 비와 눈이 하늘로부터 내려서 그리로 되돌아가지 아니하고 땅을 적셔서 소출이 나게 하며 싹이 나게 하여 파종하는 자에게는 종자를 주며 먹는 자에게는 양식을 줌과 같이"]],"9:24":[[4,"다윗의 사람들이 이르되 보소서 여호와께서 당신에게 이르시기를 내가 원수를 네 손에 넘기리니 네 생각에 좋은 대로 그에게 행하라 하시더니 이것이 그 날이니이다 하니 다윗이 일어나서 사울의 겉옷 자락을 가만히 베니라"],[16,"다윗이 사울에게 이같이 말하기를 마치매 사울이 이르되 내 아들 다윗아 이것이 네 목소리냐 하고 소리를 높여 울며"],[17,"다윗에게 이르되 나는 너를 학대하되 너는 나를 선대하니 너는 나보다 의롭도다"],[18,"네가 나 선대한 것을 오늘 나타냈나니 여호와께서 나를 네 손에 넘기셨으나 네가 나를 죽이지 아니하였도다"]],"7:4":[[11,"모세의 장인 호밥의 자손 중 겐 사람 헤벨이 떠나 게데스에 가까운 사아난님 상수리나무 곁에 이르러 장막을 쳤더라"]],"6:2":[[9,"말하되 여호와께서 이 땅을 너희에게 주신 줄을 내가 아노라 우리가 너희를 심히 두려워하고 이 땅 주민들이 다 너희 앞에서 간담이 녹나니"]],"18:42":[[5,"내가 주께 대하여 귀로 듣기만 하였사오나 이제는 눈으로 주를 뵈옵나이다"]],"19:67":[[2,"주의 도를 땅 위에, 주의 구원을 모든 나라에게 알리소서"]],"23:1":[[7,"너희의 땅은 황폐하였고 너희의 성읍들은 불에 탔고 너희의 토지는 너희 목전에서 이방인에게 삼켜졌으며 이방인에게 파괴됨 같이 황폐하였고"],[10,"너희 소돔의 관원들아 여호와의 말씀을 들을지어다 너희 고모라의 백성아 우리 하나님의 법에 귀를 기울일지어다"],[11,"여호와께서 말씀하시되 너희의 무수한 제물이 내게 무엇이 유익하뇨 나는 숫양의 번제와 살진 짐승의 기름에 배불렀고 나는 수송아지나 어린 양이나 숫염소의 피를 기뻐하지 아니하노라"],[12,"너희가 내 앞에 보이러 오니 이것을 누가 너희에게 요구하였느냐 내 마당만 밟을 뿐이니라"],[13,"헛된 제물을 다시 가져오지 말라 분향은 내가 가증히 여기는 바요 월삭과 안식일과 대회로 모이는 것도 그러하니 성회와 아울러 악을 행하는 것을 내가 견디지 못하겠노라"],[14,"내 마음이 너희의 월삭과 정한 절기를 싫어하나니 그것이 내게 무거운 짐이라 내가 지기에 곤비하였느니라"],[15,"너희가 손을 펼 때에 내가 내 눈을 너희에게서 가리고 너희가 많이 기도할지라도 내가 듣지 아니하리니 이는 너희의 손에 피가 가득함이라"],[16,"너희는 스스로 씻으며 스스로 깨끗하게 하여 내 목전에서 너희 악한 행실을 버리며 행악을 그치고"],[17,"선행을 배우며 정의를 구하며 학대 받는 자를 도와 주며 고아를 위하여 신원하며 과부를 위하여 변호하라 하셨느니라"],[18,"여호와께서 말씀하시되 오라 우리가 서로 변론하자 너희의 죄가 주홍 같을지라도 눈과 같이 희어질 것이요 진홍 같이 붉을지라도 양털 같이 희게 되리라"]],"19:18":[[2,"여호와는 나의 반석이시요 나의 요새시요 나를 건지시는 이시요 나의 하나님이시요 내가 그 안에 피할 나의 바위시요 나의 방패시요 나의 구원의 뿔이시요 나의 산성이시로다"],[7,"이에 땅이 진동하고 산들의 터도 요동하였으니 그의 진노로 말미암음이로다"],[8,"그의 코에서 연기가 오르고 입에서 불이 나와 사름이여 그 불에 숯이 피었도다"],[9,"그가 또 하늘을 드리우시고 강림하시니 그의 발 아래는 어두캄캄하도다"],[10,"그룹을 타고 다니심이여 바람 날개를 타고 높이 솟아오르셨도다"],[11,"그가 흑암을 그의 숨는 곳으로 삼으사 장막 같이 자기를 두르게 하심이여 곧 물의 흑암과 공중의 빽빽한 구름으로 그리하시도다"],[12,"그 앞에 광채로 말미암아 빽빽한 구름이 지나며 우박과 숯불이 내리도다"],[13,"여호와께서 하늘에서 우렛소리를 내시고 지존하신 이가 음성을 내시며 우박과 숯불을 내리시도다"],[14,"그의 화살을 날려 그들을 흩으심이여 많은 번개로 그들을 깨뜨리셨도다"],[15,"이럴 때에 여호와의 꾸지람과 콧김으로 말미암아 물 밑이 드러나고 세상의 터가 나타났도다"],[16,"그가 높은 곳에서 손을 펴사 나를 붙잡아 주심이여 많은 물에서 나를 건져내셨도다"],[17,"나를 강한 원수와 미워하는 자에게서 건지셨음이여 그들은 나보다 힘이 세기 때문이로다"],[18,"그들이 나의 재앙의 날에 내게 이르렀으나 여호와께서 나의 의지가 되셨도다"]],"23:31":[[5,"새가 날개 치며 그 새끼를 보호함 같이 나 만군의 여호와가 예루살렘을 보호할 것이라 그것을 호위하며 건지며 뛰어넘어 구원하리라 하셨느니라"]],"9:28":[[6,"사울이 여호와께 묻자오되 여호와께서 꿈으로도, 우림으로도, 선지자로도 그에게 대답하지 아니하시므로"],[18,"네가 여호와의 목소리를 순종하지 아니하고 그의 진노를 아말렉에게 쏟지 아니하였으므로 여호와께서 오늘 이 일을 네게 행하셨고"]],"20:11":[[18,"악인의 삯은 허무하되 공의를 뿌린 자의 상은 확실하니라"],[19,"공의를 굳게 지키는 자는 생명에 이르고 악을 따르는 자는 사망에 이르느니라"],[20,"마음이 굽은 자는 여호와께 미움을 받아도 행위가 온전한 자는 그의 기뻐하심을 받느니라"]],"48:1":[[4,"그리스도께서 하나님 곧 우리 아버지의 뜻을 따라 이 악한 세대에서 우리를 건지시려고 우리 죄를 대속하기 위하여 자기 몸을 주셨으니"]],"19:44":[[7,"오직 주께서 우리를 우리 원수들에게서 구원하시고 우리를 미워하는 자로 수치를 당하게 하셨나이다"]],"14:8":[[12,"솔로몬이 낭실 앞에 쌓은 여호와의 제단 위에 여호와께 번제를 드리되"]],"19:36":[[6,"주의 공의는 하나님의 산들과 같고 주의 심판은 큰 바다와 같으니이다 여호와여 주는 사람과 짐승을 구하여 주시나이다"]],"26:20":[[13,"그러나 이스라엘 족속이 광야에서 내게 반역하여 사람이 준행하면 그로 말미암아 삶을 얻을 나의 율례를 준행하지 아니하며 나의 규례를 멸시하였고 나의 안식일을 크게 더럽혔으므로 내가 이르기를 내가 내 분노를 광야에서 그들에게 쏟아 멸하리라 하였으나"]],"14:36":[[21,"이에 토지가 황폐하여 땅이 안식년을 누림 같이 안식하여 칠십 년을 지냈으니 여호와께서 예레미야의 입으로 하신 말씀이 이루어졌더라"]],"14:19":[[7,"그런즉 너희는 여호와를 두려워하는 마음으로 삼가 행하라 우리의 하나님 여호와께서는 사람들 앞에서 불의함도 없으시고 치우침도 없으시고 뇌물을 받는 일도 없으시니라 하니라"]],"24:9":[[24,"자랑하는 자는 이것으로 자랑할지니 곧 명철하여 나를 아는 것과 나 여호와는 사랑과 정의와 공의를 땅에 행하는 자인 줄 깨닫는 것이라 나는 이 일을 기뻐하노라 여호와의 말씀이니라"]],"35:2":[[1,"내가 내 파수하는 곳에 서며 성루에 서리라 그가 내게 무엇이라 말씀하실는지 기다리고 바라보며 나의 질문에 대하여 어떻게 대답하실는지 보리라 하였더니"]],"13:28":[[2,"이에 다윗 왕이 일어서서 이르되 나의 형제들, 나의 백성들아 내 말을 들으라 나는 여호와의 언약궤 곧 우리 하나님의 발판을 봉안할 성전을 건축할 마음이 있어서 건축할 재료를 준비하였으나"],[9,"내 아들 솔로몬아 너는 네 아버지의 하나님을 알고 온전한 마음과 기쁜 뜻으로 섬길지어다 여호와께서는 모든 마음을 감찰하사 모든 의도를 아시나니 네가 만일 그를 찾으면 만날 것이요 만일 네가 그를 버리면 그가 너를 영원히 버리시리라"],[11,"다윗이 성전의 복도와 그 집들과 그 곳간과 다락과 골방과 속죄소의 설계도를 그의 아들 솔로몬에게 주고"],[20,"또 그의 아들 솔로몬에게 이르되 너는 강하고 담대하게 이 일을 행하라 두려워하지 말며 놀라지 말라 네가 여호와의 성전 공사의 모든 일을 마치기까지 여호와 하나님 나의 하나님이 너와 함께 계시사 네게서 떠나지 아니하시고 너를 버리지 아니하시리라"]],"9:4":[[4,"이에 백성이 실로에 사람을 보내어 그룹 사이에 계신 만군의 여호와의 언약궤를 거기서 가져왔고 엘리의 두 아들 홉니와 비느하스는 하나님의 언약궤와 함께 거기에 있었더라"],[5,"여호와의 언약궤가 진영에 들어올 때에 온 이스라엘이 큰 소리로 외치매 땅이 울린지라"],[6,"블레셋 사람이 그 외치는 소리를 듣고 이르되 히브리 진영에서 큰 소리로 외침은 어찌 됨이냐 하다가 여호와의 궤가 진영에 들어온 줄을 깨달은지라"],[7,"블레셋 사람이 두려워하여 이르되 신이 진영에 이르렀도다 하고 또 이르되 우리에게 화로다 전날에는 이런 일이 없었도다"],[8,"우리에게 화로다 누가 우리를 이 능한 신들의 손에서 건지리요 그들은 광야에서 여러 가지 재앙으로 애굽인을 친 신들이니라"]],"10:6":[[2,"다윗이 일어나 자기와 함께 있는 모든 사람과 더불어 바알레유다로 가서 거기서 하나님의 궤를 메어 오려 하니 그 궤는 그룹들 사이에 좌정하신 만군의 여호와의 이름으로 불리는 것이라"],[15,"다윗과 온 이스라엘 족속이 즐거이 환호하며 나팔을 불고 여호와의 궤를 메어오니라"],[16,"여호와의 궤가 다윗 성으로 들어올 때에 사울의 딸 미갈이 창으로 내다보다가 다윗 왕이 여호와 앞에서 뛰놀며 춤추는 것을 보고 심중에 그를 업신여기니라"],[17,"여호와의 궤를 메고 들어가서 다윗이 그것을 위하여 친 장막 가운데 그 준비한 자리에 그것을 두매 다윗이 번제와 화목제를 여호와 앞에 드리니라"],[18,"다윗이 번제와 화목제 드리기를 마치고 만군의 여호와의 이름으로 백성에게 축복하고"],[19,"모든 백성 곧 온 이스라엘 무리에게 남녀를 막론하고 떡 한 개와 고기 한 조각과 건포도 떡 한 덩이씩 나누어 주매 모든 백성이 각기 집으로 돌아가니라"]],"19:80":[[2,"에브라임과 베냐민과 므낫세 앞에서 주의 능력을 나타내사 우리를 구원하러 오소서"]],"23:37":[[16,"그룹 사이에 계신 이스라엘 하나님 만군의 여호와여 주는 천하 만국에 유일하신 하나님이시라 주께서 천지를 만드셨나이다"]],"30:7":[[9,"이삭의 산당들이 황폐되며 이스라엘의 성소들이 파괴될 것이라 내가 일어나 칼로 여로보암의 집을 치리라 하시니라"]],"26:11":[[16,"그런즉 너는 말하기를 주 여호와의 말씀에 내가 비록 그들을 멀리 이방인 가운데로 쫓아내어 여러 나라에 흩었으나 그들이 도달한 나라들에서 내가 잠깐 그들에게 성소가 되리라 하셨다 하고"]],"11:6":[[1,"이스라엘 자손이 애굽 땅에서 나온 지 사백팔십 년이요 솔로몬이 이스라엘 왕이 된 지 사 년 시브월 곧 둘째 달에 솔로몬이 여호와를 위하여 성전 건축하기를 시작하였더라"]],"23:43":[[2,"네가 물 가운데로 지날 때에 내가 너와 함께 할 것이라 강을 건널 때에 물이 너를 침몰하지 못할 것이며 네가 불 가운데로 지날 때에 타지도 아니할 것이요 불꽃이 너를 사르지도 못하리니"],[4,"네가 내 눈에 보배롭고 존귀하며 내가 너를 사랑하였은즉 내가 네 대신 사람들을 내어 주며 백성들이 네 생명을 대신하리니"]],"20:28":[[1,"악인은 쫓아오는 자가 없어도 도망하나 의인은 사자 같이 담대하니라"],[13,"자기의 죄를 숨기는 자는 형통하지 못하나 죄를 자복하고 버리는 자는 불쌍히 여김을 받으리라"]],"11:4":[[13,"길르앗 라못에는 벤게벨이니 그는 길르앗에 있는 므낫세의 아들 야일의 모든 마을을 주관하였고 또 바산 아르곱 땅의 성벽과 놋빗장 있는 육십 개의 큰 성읍을 주관하였으며"],[20,"유다와 이스라엘의 인구가 바닷가의 모래 같이 많게 되매 먹고 마시며 즐거워하였으며"]],"9:17":[[5,"머리에는 놋 투구를 썼고 몸에는 비늘 갑옷을 입었으니 그 갑옷의 무게가 놋 오천 세겔이며"],[43,"블레셋 사람이 다윗에게 이르되 네가 나를 개로 여기고 막대기를 가지고 내게 나아왔느냐 하고 그의 신들의 이름으로 다윗을 저주하고"],[45,"다윗이 블레셋 사람에게 이르되 너는 칼과 창과 단창으로 내게 나아 오거니와 나는 만군의 여호와의 이름 곧 네가 모욕하는 이스라엘 군대의 하나님의 이름으로 네게 나아가노라"]],"23:49":[[14,"오직 시온이 이르기를 여호와께서 나를 버리시며 주께서 나를 잊으셨다 하였거니와"],[15,"여인이 어찌 그 젖 먹는 자식을 잊겠으며 자기 태에서 난 아들을 긍휼히 여기지 않겠느냐 그들은 혹시 잊을지라도 나는 너를 잊지 아니할 것이라"],[16,"내가 너를 내 손바닥에 새겼고 너의 성벽이 항상 내 앞에 있나니"],[17,"네 자녀들은 빨리 걸으며 너를 헐며 너를 황폐하게 하던 자들은 너를 떠나가리라"],[18,"네 눈을 들어 사방을 보라 그들이 다 모여 네게로 오느니라 나 여호와가 이르노라 내가 나의 삶으로 맹세하노니 네가 반드시 그 모든 무리를 장식처럼 몸에 차며 그것을 띠기를 신부처럼 할 것이라"]],"26:26":[[16,"그 때에 바다의 모든 왕이 그 보좌에서 내려 조복을 벗으며 수 놓은 옷을 버리고 떨림을 입듯 하고 땅에 앉아서 너로 말미암아 무시로 떨며 놀랄 것이며"]],"43:21":[[15,"그들이 조반 먹은 후에 예수께서 시몬 베드로에게 이르시되 요한의 아들 시몬아 네가 이 사람들보다 나를 더 사랑하느냐 하시니 이르되 주님 그러하나이다 내가 주님을 사랑하는 줄 주님께서 아시나이다 이르시되 내 어린 양을 먹이라 하시고"],[16,"또 두 번째 이르시되 요한의 아들 시몬아 네가 나를 사랑하느냐 하시니 이르되 주님 그러하나이다 내가 주님을 사랑하는 줄 주님께서 아시나이다 이르시되 내 양을 치라 하시고"],[17,"세 번째 이르시되 요한의 아들 시몬아 네가 나를 사랑하느냐 하시니 주께서 세 번째 네가 나를 사랑하느냐 하시므로 베드로가 근심하여 이르되 주님 모든 것을 아시오매 내가 주님을 사랑하는 줄을 주님께서 아시나이다 예수께서 이르시되 내 양을 먹이라"],[18,"내가 진실로 진실로 네게 이르노니 네가 젊어서는 스스로 띠 띠고 원하는 곳으로 다녔거니와 늙어서는 네 팔을 벌리리니 남이 네게 띠 띠우고 원하지 아니하는 곳으로 데려가리라"],[19,"이 말씀을 하심은 베드로가 어떠한 죽음으로 하나님께 영광을 돌릴 것을 가리키심이러라 이 말씀을 하시고 베드로에게 이르시되 나를 따르라 하시니"],[20,"베드로가 돌이켜 예수께서 사랑하시는 그 제자가 따르는 것을 보니 그는 만찬석에서 예수의 품에 의지하여 주님 주님을 파는 자가 누구오니이까 묻던 자더라"],[21,"이에 베드로가 그를 보고 예수께 여짜오되 주님 이 사람은 어떻게 되겠사옵나이까"],[22,"예수께서 이르시되 내가 올 때까지 그를 머물게 하고자 할지라도 네게 무슨 상관이냐 너는 나를 따르라 하시더라"],[23,"이 말씀이 형제들에게 나가서 그 제자는 죽지 아니하겠다 하였으나 예수의 말씀은 그가 죽지 않겠다 하신 것이 아니라 내가 올 때까지 그를 머물게 하고자 할지라도 네게 무슨 상관이냐 하신 것이러라"]],"7:17":[[5,"그 사람 미가에게 신당이 있으므로 그가 에봇과 드라빔을 만들고 한 아들을 세워 그의 제사장으로 삼았더라"],[7,"유다 가족에 속한 유다 베들레헴에 한 청년이 있었으니 그는 레위인으로서 거기서 거류하였더라"],[8,"그 사람이 거주할 곳을 찾고자 하여 그 성읍 유다 베들레헴을 떠나 가다가 에브라임 산지로 가서 미가의 집에 이르매"],[9,"미가가 그에게 묻되 너는 어디서부터 오느냐 하니 그가 이르되 나는 유다 베들레헴의 레위인으로서 거류할 곳을 찾으러 가노라 하는지라"],[10,"미가가 그에게 이르되 네가 나와 함께 거주하며 나를 위하여 아버지와 제사장이 되라 내가 해마다 은 열과 의복 한 벌과 먹을 것을 주리라 하므로 그 레위인이 들어갔더라"],[11,"그 레위인이 그 사람과 함께 거주하기를 만족하게 생각했으니 이는 그 청년이 미가의 아들 중 하나 같이 됨이라"],[12,"미가가 그 레위인을 거룩하게 구별하매 그 청년이 미가의 제사장이 되어 그 집에 있었더라"],[13,"이에 미가가 이르되 레위인이 내 제사장이 되었으니 이제 여호와께서 내게 복 주실 줄을 아노라 하니라"]],"11:19":[[16,"너는 또 님시의 아들 예후에게 기름을 부어 이스라엘의 왕이 되게 하고 또 아벨므홀라 사밧의 아들 엘리사에게 기름을 부어 너를 대신하여 선지자가 되게 하라"]],"13:11":[[3,"이에 이스라엘의 모든 장로가 헤브론에 있는 왕에게로 나아가니 헤브론에서 다윗이 그들과 여호와 앞에 언약을 맺으매 그들이 다윗에게 기름을 부어 이스라엘의 왕으로 삼으니 여호와께서 사무엘을 통하여 전하신 말씀대로 되었더라"]],"33:5":[[2,"베들레헴 에브라다야 너는 유다 족속 중에 작을지라도 이스라엘을 다스릴 자가 네게서 내게로 나올 것이라 그의 근본은 상고에, 영원에 있느니라"],[15,"내가 또 진노와 분노로 순종하지 아니한 나라에 갚으리라 하셨느니라"]],"23:7":[[14,"그러므로 주께서 친히 징조를 너희에게 주실 것이라 보라 처녀가 잉태하여 아들을 낳을 것이요 그의 이름을 임마누엘이라 하리라"]],"27:9":[[25,"그러므로 너는 깨달아 알지니라 예루살렘을 중건하라는 영이 날 때부터 기름 부음을 받은 자 곧 왕이 일어나기까지 일곱 이레와 예순두 이레가 지날 것이요 그 곤란한 동안에 성이 중건되어 광장과 거리가 세워질 것이며"]],"19:45":[[8,"왕의 모든 옷은 몰약과 침향과 육계의 향기가 있으며 상아궁에서 나오는 현악은 왕을 즐겁게 하도다"]],"19:141":[[2,"나의 기도가 주의 앞에 분향함과 같이 되며 나의 손 드는 것이 저녁 제사 같이 되게 하소서"]],"13:2":[[18,"헤스론의 아들 갈렙이 그의 아내 아수바와 여리옷에게서 아들을 낳았으니 그가 낳은 아들들은 예셀과 소밥과 아르돈이며"],[19,"아수바가 죽은 후에 갈렙이 또 에브랏에게 장가 들었더니 에브랏이 그에게 훌을 낳아 주었고"],[20,"훌은 우리를 낳고 우리는 브살렐을 낳았더라"],[23,"그술과 아람이 야일의 성읍들과 그낫과 그에 딸린 성읍들 모두 육십을 그들에게서 빼앗았으며 이들은 다 길르앗의 아버지 마길의 자손이었더라"]],"26:36":[[26,"또 새 영을 너희 속에 두고 새 마음을 너희에게 주되 너희 육신에서 굳은 마음을 제거하고 부드러운 마음을 줄 것이며"],[27,"또 내 영을 너희 속에 두어 너희로 내 율례를 행하게 하리니 너희가 내 규례를 지켜 행할지라"],[28,"내가 너희 조상들에게 준 땅에서 너희가 거주하면서 내 백성이 되고 나는 너희 하나님이 되리라"]],"28:11":[[7,"내 백성이 끝끝내 내게서 물러가나니 비록 그들을 불러 위에 계신 이에게로 돌아오라 할지라도 일어나는 자가 하나도 없도다"],[8,"에브라임이여 내가 어찌 너를 놓겠느냐 이스라엘이여 내가 어찌 너를 버리겠느냐 내가 어찌 너를 아드마 같이 놓겠느냐 어찌 너를 스보임 같이 두겠느냐 내 마음이 내 속에서 돌이키어 나의 긍휼이 온전히 불붙듯 하도다"]],"9:15":[[4,"사울이 백성을 소집하고 그들을 들라임에서 세어 보니 보병이 이십만 명이요 유다 사람이 만 명이라"],[5,"사울이 아말렉 성에 이르러 골짜기에 복병시키니라"],[6,"사울이 겐 사람에게 이르되 아말렉 사람 중에서 떠나 가라 그들과 함께 너희를 멸하게 될까 하노라 이스라엘 모든 자손이 애굽에서 올라올 때에 너희가 그들을 선대하였느니라 이에 겐 사람이 아말렉 사람 중에서 떠나니라"],[7,"사울이 하윌라에서부터 애굽 앞 술에 이르기까지 아말렉 사람을 치고"],[8,"아말렉 사람의 왕 아각을 사로잡고 칼날로 그의 모든 백성을 진멸하였으되"],[9,"사울과 백성이 아각과 그의 양과 소의 가장 좋은 것 또는 기름진 것과 어린 양과 모든 좋은 것을 남기고 진멸하기를 즐겨 아니하고 가치 없고 하찮은 것은 진멸하니라"],[10,"여호와의 말씀이 사무엘에게 임하니라 이르시되"],[11,"내가 사울을 왕으로 세운 것을 후회하노니 그가 돌이켜서 나를 따르지 아니하며 내 명령을 행하지 아니하였음이니라 하신지라 사무엘이 근심하여 온 밤을 여호와께 부르짖으니라"],[12,"사무엘이 사울을 만나려고 아침에 일찍이 일어났더니 어떤 사람이 사무엘에게 말하여 이르되 사울이 갈멜에 이르러 자기를 위하여 기념비를 세우고 발길을 돌려 길갈로 내려갔다 하는지라"],[13,"사무엘이 사울에게 이른즉 사울이 그에게 이르되 원하건대 당신은 여호와께 복을 받으소서 내가 여호와의 명령을 행하였나이다 하니"],[14,"사무엘이 이르되 그러면 내 귀에 들려오는 이 양의 소리와 내게 들리는 소의 소리는 어찌 됨이니이까 하니라"],[15,"사울이 이르되 그것은 무리가 아말렉 사람에게서 끌어 온 것인데 백성이 당신의 하나님 여호와께 제사하려 하여 양들과 소들 중에서 가장 좋은 것을 남김이요 그 외의 것은 우리가 진멸하였나이다 하는지라"],[16,"사무엘이 사울에게 이르되 가만히 계시옵소서 간 밤에 여호와께서 내게 이르신 것을 왕에게 말하리이다 하니 그가 이르되 말씀하소서"],[17,"사무엘이 이르되 왕이 스스로 작게 여길 그 때에 이스라엘 지파의 머리가 되지 아니하셨나이까 여호와께서 왕에게 기름을 부어 이스라엘 왕을 삼으시고"],[18,"또 여호와께서 왕을 길로 보내시며 이르시기를 가서 죄인 아말렉 사람을 진멸하되 다 없어지기까지 치라 하셨거늘"],[19,"어찌하여 왕이 여호와의 목소리를 청종하지 아니하고 탈취하기에만 급하여 여호와께서 악하게 여기시는 일을 행하였나이까"],[20,"사울이 사무엘에게 이르되 나는 실로 여호와의 목소리를 청종하여 여호와께서 보내신 길로 가서 아말렉 왕 아각을 끌어 왔고 아말렉 사람들을 진멸하였으나"],[21,"다만 백성이 그 마땅히 멸할 것 중에서 가장 좋은 것으로 길갈에서 당신의 하나님 여호와께 제사하려고 양과 소를 끌어 왔나이다 하는지라"],[22,"사무엘이 이르되 여호와께서 번제와 다른 제사를 그의 목소리를 청종하는 것을 좋아하심 같이 좋아하시겠나이까 순종이 제사보다 낫고 듣는 것이 숫양의 기름보다 나으니"],[23,"이는 거역하는 것은 점치는 죄와 같고 완고한 것은 사신 우상에게 절하는 죄와 같음이라 왕이 여호와의 말씀을 버렸으므로 여호와께서도 왕을 버려 왕이 되지 못하게 하셨나이다 하니"],[29,"이스라엘의 지존자는 거짓이나 변개함이 없으시니 그는 사람이 아니시므로 결코 변개하지 않으심이니이다 하니"]],"19:7":[[3,"여호와 내 하나님이여 내가 이런 일을 행하였거나 내 손에 죄악이 있거나"],[8,"여호와께서 만민에게 심판을 행하시오니 여호와여 나의 의와 나의 성실함을 따라 나를 심판하소서"],[9,"악인의 악을 끊고 의인을 세우소서 의로우신 하나님이 사람의 마음과 양심을 감찰하시나이다"],[10,"나의 방패는 마음이 정직한 자를 구원하시는 하나님께 있도다"],[11,"하나님은 의로우신 재판장이심이여 매일 분노하시는 하나님이시로다"]],"24:29":[[12,"너희가 내게 부르짖으며 내게 와서 기도하면 내가 너희들의 기도를 들을 것이요"],[14,"이것은 여호와의 말씀이니라 나는 너희들을 만날 것이며 너희를 포로된 중에서 다시 돌아오게 하되 내가 쫓아 보내었던 나라들과 모든 곳에서 모아 사로잡혀 떠났던 그 곳으로 돌아오게 하리라 이것은 여호와의 말씀이니라"]],"35:1":[[13,"주께서는 눈이 정결하시므로 악을 차마 보지 못하시며 패역을 차마 보지 못하시거늘 어찌하여 거짓된 자들을 방관하시며 악인이 자기보다 의로운 사람을 삼키는데도 잠잠하시나이까"]],"16:9":[[6,"오직 주는 여호와시라 하늘과 하늘들의 하늘과 일월 성신과 땅과 땅 위의 만물과 바다와 그 가운데 모든 것을 지으시고 다 보존하시오니 모든 천군이 주께 경배하나이다"],[17,"거역하며 주께서 그들 가운데에서 행하신 기사를 기억하지 아니하고 목을 굳게 하며 패역하여 스스로 한 우두머리를 세우고 종 되었던 땅으로 돌아가고자 하였나이다 그러나 주께서는 용서하시는 하나님이시라 은혜로우시며 긍휼히 여기시며 더디 노하시며 인자가 풍부하시므로 그들을 버리지 아니하셨나이다"],[21,"사십 년 동안 들에서 기르시되 부족함이 없게 하시므로 그 옷이 해어지지 아니하였고 발이 부르트지 아니하였사오며"]],"19:86":[[15,"그러나 주여 주는 긍휼히 여기시며 은혜를 베푸시며 노하기를 더디하시며 인자와 진실이 풍성하신 하나님이시오니"]],"29:2":[[12,"여호와의 말씀에 너희는 이제라도 금식하고 울며 애통하고 마음을 다하여 내게로 돌아오라 하셨나니"],[13,"너희는 옷을 찢지 말고 마음을 찢고 너희 하나님 여호와께로 돌아올지어다 그는 은혜로우시며 자비로우시며 노하기를 더디하시며 인애가 크시사 뜻을 돌이켜 재앙을 내리지 아니하시나니"]],"32:4":[[2,"여호와께 기도하여 이르되 여호와여 내가 고국에 있을 때에 이러하겠다고 말씀하지 아니하였나이까 그러므로 내가 빨리 다시스로 도망하였사오니 주께서는 은혜로우시며 자비로우시며 노하기를 더디하시며 인애가 크시사 뜻을 돌이켜 재앙을 내리지 아니하시는 하나님이신 줄을 내가 알았음이니이다"]],"9:7":[[3,"사무엘이 이스라엘 온 족속에게 말하여 이르되 만일 너희가 전심으로 여호와께 돌아오려거든 이방 신들과 아스다롯을 너희 중에서 제거하고 너희 마음을 여호와께로 향하여 그만을 섬기라 그리하면 너희를 블레셋 사람의 손에서 건져내시리라"],[9,"사무엘이 젖 먹는 어린 양 하나를 가져다가 온전한 번제를 여호와께 드리고 이스라엘을 위하여 여호와께 부르짖으매 여호와께서 응답하셨더라"]],"11:11":[[5,"이는 시돈 사람의 여신 아스다롯을 따르고 암몬 사람의 가증한 밀곰을 따름이라"],[32,"오직 내 종 다윗을 위하고 이스라엘 모든 지파 중에서 택한 성읍 예루살렘을 위하여 한 지파를 솔로몬에게 주리니"],[34,"그러나 내가 택한 내 종 다윗이 내 명령과 내 법도를 지켰으므로 내가 그를 위하여 솔로몬의 생전에는 온 나라를 그의 손에서 빼앗지 아니하고 주관하게 하려니와"]],"12:21":[[4,"여호와께서 전에 이르시기를 내가 내 이름을 예루살렘에 두리라 하신 여호와의 성전에 제단들을 쌓고"],[7,"또 자기가 만든 아로새긴 아세라 목상을 성전에 세웠더라 옛적에 여호와께서 이 성전에 대하여 다윗과 그의 아들 솔로몬에게 이르시기를 내가 이스라엘의 모든 지파 중에서 택한 이 성전과 예루살렘에 내 이름을 영원히 둘지라"]],"13:29":[[2,"내가 이미 내 하나님의 성전을 위하여 힘을 다하여 준비하였나니 곧 기구를 만들 금과 은과 놋과 철과 나무와 또 마노와 가공할 검은 보석과 채석과 다른 모든 보석과 옥돌이 매우 많으며"],[3,"성전을 위하여 준비한 이 모든 것 외에도 내 마음이 내 하나님의 성전을 사모하므로 내가 사유한 금, 은으로 내 하나님의 성전을 위하여 드렸노니"],[4,"곧 오빌의 금 삼천 달란트와 순은 칠천 달란트라 모든 성전 벽에 입히며"],[5,"금, 은 그릇을 만들며 장인의 손으로 하는 모든 일에 쓰게 하였노니 오늘 누가 즐거이 손에 채워 여호와께 드리겠느냐 하는지라"],[6,"이에 모든 가문의 지도자들과 이스라엘 모든 지파의 지도자들과 천부장과 백부장과 왕의 사무관이 다 즐거이 드리되"],[7,"하나님의 성전 공사를 위하여 금 오천 달란트와 금 만 다릭 은 만 달란트와 놋 만 팔천 달란트와 철 십만 달란트를 드리고"],[8,"보석을 가진 모든 사람은 게르손 사람 여히엘의 손에 맡겨 여호와의 성전 곳간에 드렸더라"],[9,"백성들은 자원하여 드렸으므로 기뻐하였으니 곧 그들이 성심으로 여호와께 자원하여 드렸으므로 다윗 왕도 심히 기뻐하니라"],[14,"나와 내 백성이 무엇이기에 이처럼 즐거운 마음으로 드릴 힘이 있었나이까 모든 것이 주께로 말미암았사오니 우리가 주의 손에서 받은 것으로 주께 드렸을 뿐이니이다"]],"19:24":[[1,"땅과 거기에 충만한 것과 세계와 그 가운데에 사는 자들은 다 여호와의 것이로다"],[8,"영광의 왕이 누구시냐 강하고 능한 여호와시요 전쟁에 능한 여호와시로다"]],"57:1":[[6,"이로써 네 믿음의 교제가 우리 가운데 있는 선을 알게 하고 그리스도께 이르도록 역사하느니라"],[14,"다만 네 승낙이 없이는 내가 아무 것도 하기를 원하지 아니하노니 이는 너의 선한 일이 억지 같이 되지 아니하고 자의로 되게 하려 함이라"],[20,"오 형제여 나로 주 안에서 너로 말미암아 기쁨을 얻게 하고 내 마음이 그리스도 안에서 평안하게 하라"]],"11:18":[[21,"엘리야가 모든 백성에게 가까이 나아가 이르되 너희가 어느 때까지 둘 사이에서 머뭇머뭇 하려느냐 여호와가 만일 하나님이면 그를 따르고 바알이 만일 하나님이면 그를 따를지니라 하니 백성이 말 한마디도 대답하지 아니하는지라"],[30,"엘리야가 모든 백성을 향하여 이르되 내게로 가까이 오라 백성이 다 그에게 가까이 가매 그가 무너진 여호와의 제단을 수축하되"],[31,"야곱의 아들들의 지파의 수효를 따라 엘리야가 돌 열두 개를 취하니 이 야곱은 옛적에 여호와의 말씀이 임하여 이르시기를 네 이름을 이스라엘이라 하리라 하신 자더라"],[32,"그가 여호와의 이름을 의지하여 그 돌로 제단을 쌓고 제단을 돌아가며 곡식 종자 두 세아를 둘 만한 도랑을 만들고"],[33,"또 나무를 벌이고 송아지의 각을 떠서 나무 위에 놓고 이르되 통 넷에 물을 채워다가 번제물과 나무 위에 부으라 하고"],[34,"또 이르되 다시 그리하라 하여 다시 그리하니 또 이르되 세 번째로 그리하라 하여 세 번째로 그리하니"],[35,"물이 제단으로 두루 흐르고 도랑에도 물이 가득 찼더라"],[36,"저녁 소제 드릴 때에 이르러 선지자 엘리야가 나아가서 말하되 아브라함과 이삭과 이스라엘의 하나님 여호와여 주께서 이스라엘 중에서 하나님이신 것과 내가 주의 종인 것과 내가 주의 말씀대로 이 모든 일을 행하는 것을 오늘 알게 하옵소서"],[37,"여호와여 내게 응답하옵소서 내게 응답하옵소서 이 백성에게 주 여호와는 하나님이신 것과 주는 그들의 마음을 되돌이키심을 알게 하옵소서 하매"],[38,"이에 여호와의 불이 내려서 번제물과 나무와 돌과 흙을 태우고 또 도랑의 물을 핥은지라"],[39,"모든 백성이 보고 엎드려 말하되 여호와 그는 하나님이시로다 여호와 그는 하나님이시로다 하니"]],"9:3":[[3,"하나님의 등불은 아직 꺼지지 아니하였으며 사무엘은 하나님의 궤 있는 여호와의 전 안에 누웠더니"],[14,"그러므로 내가 엘리의 집에 대하여 맹세하기를 엘리 집의 죄악은 제물로나 예물로나 영원히 속죄함을 받지 못하리라 하였노라 하셨더라"],[19,"사무엘이 자라매 여호와께서 그와 함께 계셔서 그의 말이 하나도 땅에 떨어지지 않게 하시니"]],"26:1":[[4,"내가 보니 북쪽에서부터 폭풍과 큰 구름이 오는데 그 속에서 불이 번쩍번쩍하여 빛이 그 사방에 비치며 그 불 가운데 단 쇠 같은 것이 나타나 보이고"],[5,"그 속에서 네 생물의 형상이 나타나는데 그들의 모양이 이러하니 그들에게 사람의 형상이 있더라"],[6,"그들에게 각각 네 얼굴과 네 날개가 있고"],[7,"그들의 다리는 곧은 다리요 그들의 발바닥은 송아지 발바닥 같고 광낸 구리 같이 빛나며"],[8,"그 사방 날개 밑에는 각각 사람의 손이 있더라 그 네 생물의 얼굴과 날개가 이러하니"],[9,"날개는 다 서로 연하였으며 갈 때에는 돌이키지 아니하고 일제히 앞으로 곧게 행하며"],[10,"그 얼굴들의 모양은 넷의 앞은 사람의 얼굴이요 넷의 오른쪽은 사자의 얼굴이요 넷의 왼쪽은 소의 얼굴이요 넷의 뒤는 독수리의 얼굴이니"],[11,"그 얼굴은 그러하며 그 날개는 들어 펴서 각기 둘씩 서로 연하였고 또 둘은 몸을 가렸으며"],[12,"영이 어떤 쪽으로 가면 그 생물들도 그대로 가되 돌이키지 아니하고 일제히 앞으로 곧게 행하며"],[13,"또 생물들의 모양은 타는 숯불과 횃불 모양 같은데 그 불이 그 생물 사이에서 오르락내리락 하며 그 불은 광채가 있고 그 가운데에서는 번개가 나며"],[14,"그 생물들은 번개 모양 같이 왕래하더라"],[15,"내가 그 생물들을 보니 그 생물들 곁에 있는 땅 위에는 바퀴가 있는데 그 네 얼굴을 따라 하나씩 있고"],[16,"그 바퀴의 모양과 그 구조는 황옥 같이 보이는데 그 넷은 똑같은 모양을 가지고 있으며 그들의 모양과 구조는 바퀴 안에 바퀴가 있는 것 같으며"],[17,"그들이 갈 때에는 사방으로 향한 대로 돌이키지 아니하고 가며"],[18,"그 둘레는 높고 무서우며 그 네 둘레로 돌아가면서 눈이 가득하며"],[19,"그 생물들이 갈 때에 바퀴들도 그 곁에서 가고 그 생물들이 땅에서 들릴 때에 바퀴들도 들려서"],[20,"영이 어떤 쪽으로 가면 생물들도 영이 가려 하는 곳으로 가고 바퀴들도 그 곁에서 들리니 이는 생물의 영이 그 바퀴들 가운데에 있음이니라"],[21,"그들이 가면 이들도 가고 그들이 서면 이들도 서고 그들이 땅에서 들릴 때에는 이들도 그 곁에서 들리니 이는 생물의 영이 그 바퀴들 가운데에 있음이더라"]],"15:8":[[35,"사로잡혔던 자의 자손 곧 이방에서 돌아온 자들이 이스라엘의 하나님께 번제를 드렸는데 이스라엘 전체를 위한 수송아지가 열두 마리요 또 숫양이 아흔여섯 마리요 어린 양이 일흔일곱 마리요 또 속죄제의 숫염소가 열두 마리니 모두 여호와께 드린 번제물이라"]],"55:1":[[2,"사랑하는 아들 디모데에게 편지하노니 하나님 아버지와 그리스도 예수 우리 주께로부터 은혜와 긍휼과 평강이 네게 있을지어다"],[7,"하나님이 우리에게 주신 것은 두려워하는 마음이 아니요 오직 능력과 사랑과 절제하는 마음이니"],[10,"이제는 우리 구주 그리스도 예수의 나타나심으로 말미암아 나타났으니 그는 사망을 폐하시고 복음으로써 생명과 썩지 아니할 것을 드러내신지라"],[14,"우리 안에 거하시는 성령으로 말미암아 네게 부탁한 아름다운 것을 지키라"]],"20:5":[[3,"대저 음녀의 입술은 꿀을 떨어뜨리며 그의 입은 기름보다 미끄러우나"]],"47:2":[[15,"우리는 구원 받는 자들에게나 망하는 자들에게나 하나님 앞에서 그리스도의 향기니"]],"9:10":[[1,"이에 사무엘이 기름병을 가져다가 사울의 머리에 붓고 입맞추며 이르되 여호와께서 네게 기름을 부으사 그의 기업의 지도자로 삼지 아니하셨느냐"],[27,"어떤 불량배는 이르되 이 사람이 어떻게 우리를 구원하겠느냐 하고 멸시하며 예물을 바치지 아니하였으나 그는 잠잠하였더라"]],"10:8":[[2,"다윗이 또 모압을 쳐서 그들에게 땅에 엎드리게 하고 줄로 재어 그 두 줄 길이의 사람은 죽이고 한 줄 길이의 사람들은 살리니 모압 사람들이 다윗의 종들이 되어 조공을 드리니라"]],"14:17":[[11,"블레셋 사람들 중에서는 여호사밧에게 예물을 드리며 은으로 조공을 바쳤고 아라비아 사람들도 짐승 떼 곧 숫양 칠천칠백 마리와 숫염소 칠천칠백 마리를 드렸더라"]],"14:31":[[5,"왕의 명령이 내리자 곧 이스라엘 자손이 곡식과 포도주와 기름과 꿀과 밭의 모든 소산의 첫 열매들을 풍성히 드렸고 또 모든 것의 십일조를 많이 가져왔으며"]],"14:13":[[5,"이스라엘 하나님 여호와께서 소금 언약으로 이스라엘 나라를 영원히 다윗과 그의 자손에게 주신 것을 너희가 알 것 아니냐"],[9,"너희가 아론 자손인 여호와의 제사장들과 레위 사람들을 쫓아내고 이방 백성들의 풍속을 따라 제사장을 삼지 아니하였느냐 누구를 막론하고 어린 수송아지 한 마리와 숫양 일곱 마리를 끌고 와서 장립을 받고자 하는 자마다 허무한 신들의 제사장이 될 수 있도다"]],"7:8":[[7,"기드온이 이르되 그러면 여호와께서 세바와 살문나를 내 손에 넘겨 주신 후에 내가 들가시와 찔레로 너희 살을 찢으리라 하고"],[11,"적군이 안심하고 있는 중에 기드온이 노바와 욕브하 동쪽 장막에 거주하는 자의 길로 올라가서 그 적진을 치니"],[22,"그 때에 이스라엘 사람들이 기드온에게 이르되 당신이 우리를 미디안의 손에서 구원하셨으니 당신과 당신의 아들과 당신의 손자가 우리를 다스리소서 하는지라"],[26,"기드온이 요청한 금 귀고리의 무게가 금 천칠백 세겔이요 그 외에 또 초승달 장식들과 패물과 미디안 왕들이 입었던 자색 의복과 또 그 외에 그들의 낙타 목에 둘렀던 사슬이 있었더라"]],"9:11":[[1,"암몬 사람 나하스가 올라와서 길르앗 야베스에 맞서 진 치매 야베스 모든 사람들이 나하스에게 이르되 우리와 언약하자 그리하면 우리가 너를 섬기리라 하니"],[2,"암몬 사람 나하스가 그들에게 이르되 내가 너희 오른 눈을 다 빼야 너희와 언약하리라 내가 온 이스라엘을 이같이 모욕하리라"],[3,"야베스 장로들이 그에게 이르되 우리에게 이레 동안 말미를 주어 우리가 이스라엘 온 지역에 전령들을 보내게 하라 만일 우리를 구원할 자가 없으면 네게 나아가리라 하니라"],[4,"이에 전령들이 사울이 사는 기브아에 이르러 이 말을 백성에게 전하매 모든 백성이 소리를 높여 울더니"],[5,"마침 사울이 밭에서 소를 몰고 오다가 이르되 백성이 무슨 일로 우느냐 하니 그들이 야베스 사람의 말을 전하니라"],[6,"사울이 이 말을 들을 때에 하나님의 영에게 크게 감동되매 그의 노가 크게 일어나"],[7,"한 겨리의 소를 잡아 각을 뜨고 전령들의 손으로 그것을 이스라엘 모든 지역에 두루 보내어 이르되 누구든지 나와서 사울과 사무엘을 따르지 아니하면 그의 소들도 이와 같이 하리라 하였더니 여호와의 두려움이 백성에게 임하매 그들이 한 사람 같이 나온지라"],[8,"사울이 베섹에서 그들의 수를 세어 보니 이스라엘 자손이 삼십만 명이요 유다 사람이 삼만 명이더라"],[9,"무리가 모든 전령들에게 이르되 너희는 길르앗 야베스 사람에게 이같이 이르기를 내일 해가 더울 때에 너희가 구원을 받으리라 하라 전령들이 돌아가서 야베스 사람들에게 전하매 그들이 기뻐하니라"],[10,"야베스 사람들이 이에 이르되 우리가 내일 너희에게 나아가리니 너희 생각에 좋을 대로 우리에게 다 행하라 하니라"],[11,"이튿날 사울이 백성을 삼 대로 나누고 새벽에 적진 한가운데로 들어가서 날이 더울 때까지 암몬 사람들을 치매 남은 자가 다 흩어져서 둘도 함께 한 자가 없었더라"],[15,"모든 백성이 길갈로 가서 거기서 여호와 앞에서 사울을 왕으로 삼고 길갈에서 여호와 앞에 화목제를 드리고 사울과 이스라엘 모든 사람이 거기서 크게 기뻐하니라"]],"11:8":[[27,"하나님이 참으로 땅에 거하시리이까 하늘과 하늘들의 하늘이라도 주를 용납하지 못하겠거든 하물며 내가 건축한 이 성전이오리이까"],[28,"그러나 내 하나님 여호와여 주의 종의 기도와 간구를 돌아보시며 이 종이 오늘 주 앞에서 부르짖음과 비는 기도를 들으시옵소서"],[46,"범죄하지 아니하는 사람이 없사오니 그들이 주께 범죄함으로 주께서 그들에게 진노하사 그들을 적국에게 넘기시매 적국이 그들을 사로잡아 원근을 막론하고 적국의 땅으로 끌어간 후에"],[47,"그들이 사로잡혀 간 땅에서 스스로 깨닫고 그 사로잡은 자의 땅에서 돌이켜 주께 간구하기를 우리가 범죄하여 반역을 행하며 악을 지었나이다 하며"],[48,"자기를 사로잡아 간 적국의 땅에서 온 마음과 온 뜻으로 주께 돌아와서 주께서 그들의 조상들에게 주신 땅 곧 주께서 택하신 성읍과 내가 주의 이름을 위하여 건축한 성전 있는 쪽을 향하여 주께 기도하거든"],[49,"주는 계신 곳 하늘에서 그들의 기도와 간구를 들으시고 그들의 일을 돌아보시오며"],[50,"주께 범죄한 백성을 용서하시며 주께 범한 그 모든 허물을 사하시고 그들을 사로잡아 간 자 앞에서 그들로 불쌍히 여김을 얻게 하사 그 사람들로 그들을 불쌍히 여기게 하옵소서"],[51,"그들은 주께서 철 풀무 같은 애굽에서 인도하여 내신 주의 백성, 주의 소유가 됨이니이다"],[56,"여호와를 찬송할지로다 그가 말씀하신 대로 그의 백성 이스라엘에게 태평을 주셨으니 그 종 모세를 통하여 무릇 말씀하신 그 모든 좋은 약속이 하나도 이루어지지 아니함이 없도다"],[63,"솔로몬이 화목제의 희생제물을 드렸으니 곧 여호와께 드린 소가 이만 이천 마리요 양이 십이만 마리라 이와 같이 왕과 모든 이스라엘 자손이 여호와의 성전의 봉헌식을 행하였는데"],[64,"그 날에 왕이 여호와의 성전 앞뜰 가운데를 거룩히 구별하고 거기서 번제와 소제와 감사제물의 기름을 드렸으니 이는 여호와의 앞 놋제단이 작으므로 번제물과 소제물과 화목제의 기름을 다 용납할 수 없음이라"],[65,"그 때에 솔로몬이 칠 일과 칠 일 도합 십사 일간을 우리 하나님 여호와 앞에서 절기로 지켰는데 하맛 어귀에서부터 애굽 강까지의 온 이스라엘의 큰 회중이 모여 그와 함께 하였더니"],[66,"여덟째 날에 솔로몬이 백성을 돌려보내매 백성이 왕을 위하여 축복하고 자기 장막으로 돌아가는데 여호와께서 그의 종 다윗과 그의 백성 이스라엘에게 베푸신 모든 은혜로 말미암아 기뻐하며 마음에 즐거워하였더라"]],"28:4":[[8,"그들이 내 백성의 속죄제물을 먹고 그 마음을 그들의 죄악에 두는도다"]],"39:3":[[8,"사람이 어찌 하나님의 것을 도둑질하겠느냐 그러나 너희는 나의 것을 도둑질하고도 말하기를 우리가 어떻게 주의 것을 도둑질하였나이까 하는도다 이는 곧 십일조와 봉헌물이라"],[9,"너희 곧 온 나라가 나의 것을 도둑질하였으므로 너희가 저주를 받았느니라"],[10,"만군의 여호와가 이르노라 너희의 온전한 십일조를 창고에 들여 나의 집에 양식이 있게 하고 그것으로 나를 시험하여 내가 하늘 문을 열고 너희에게 복을 쌓을 곳이 없도록 붓지 아니하나 보라"],[11,"만군의 여호와가 이르노라 내가 너희를 위하여 메뚜기를 금하여 너희 토지 소산을 먹어 없애지 못하게 하며 너희 밭의 포도나무 열매가 기한 전에 떨어지지 않게 하리니"],[12,"너희 땅이 아름다워지므로 모든 이방인들이 너희를 복되다 하리라 만군의 여호와의 말이니라"]],"20:14":[[9,"미련한 자는 죄를 심상히 여겨도 정직한 자 중에는 은혜가 있느니라"]],"12:12":[[16,"속건제의 은과 속죄제의 은은 여호와의 성전에 드리지 아니하고 제사장에게 돌렸더라"]],"28:8":[[11,"에브라임은 죄를 위하여 제단을 많이 만들더니 그 제단이 그에게 범죄하게 하는 것이 되었도다"],[12,"내가 그를 위하여 내 율법을 만 가지로 기록하였으나 그들은 이상한 것으로 여기도다"]],"24:22":[[13,"불의로 그 집을 세우며 부정하게 그 다락방을 지으며 자기의 이웃을 고용하고 그의 품삯을 주지 아니하는 자에게 화 있을진저"]],"23:64":[[5,"주께서 기쁘게 공의를 행하는 자와 주의 길에서 주를 기억하는 자를 선대하시거늘 우리가 범죄하므로 주께서 진노하셨사오며 이 현상이 이미 오래 되었사오니 우리가 어찌 구원을 얻을 수 있으리이까"]],"19:100":[[2,"기쁨으로 여호와를 섬기며 노래하면서 그의 앞에 나아갈지어다"],[3,"여호와가 우리 하나님이신 줄 너희는 알지어다 그는 우리를 지으신 이요 우리는 그의 것이니 그의 백성이요 그의 기르시는 양이로다"],[4,"감사함으로 그의 문에 들어가며 찬송함으로 그의 궁정에 들어가서 그에게 감사하며 그의 이름을 송축할지어다"]],"19:119":[[67,"고난 당하기 전에는 내가 그릇 행하였더니 이제는 주의 말씀을 지키나이다"],[105,"주의 말씀은 내 발에 등이요 내 길에 빛이니이다"],[151,"여호와여 주께서 가까이 계시오니 주의 모든 계명들은 진리니이다"],[172,"주의 모든 계명들이 의로우므로 내 혀가 주의 말씀을 노래하리이다"]],"19:27":[[1,"여호와는 나의 빛이요 나의 구원이시니 내가 누구를 두려워하리요 여호와는 내 생명의 능력이시니 내가 누구를 무서워하리요"],[14,"너는 여호와를 기다릴지어다 강하고 담대하며 여호와를 기다릴지어다"]],"23:2":[[2,"말일에 여호와의 전의 산이 모든 산 꼭대기에 굳게 설 것이요 모든 작은 산 위에 뛰어나리니 만방이 그리로 모여들 것이라"],[3,"많은 백성이 가며 이르기를 오라 우리가 여호와의 산에 오르며 야곱의 하나님의 전에 이르자 그가 그의 길을 우리에게 가르치실 것이라 우리가 그 길로 행하리라 하리니 이는 율법이 시온에서부터 나올 것이요 여호와의 말씀이 예루살렘에서부터 나올 것임이니라"],[4,"그가 열방 사이에 판단하시며 많은 백성을 판결하시리니 무리가 그들의 칼을 쳐서 보습을 만들고 그들의 창을 쳐서 낫을 만들 것이며 이 나라와 저 나라가 다시는 칼을 들고 서로 치지 아니하며 다시는 전쟁을 연습하지 아니하리라"],[5,"야곱 족속아 오라 우리가 여호와의 빛에 행하자"]],"33:7":[[8,"나의 대적이여 나로 말미암아 기뻐하지 말지어다 나는 엎드러질지라도 일어날 것이요 어두운 데에 앉을지라도 여호와께서 나의 빛이 되실 것임이로다"],[18,"주와 같은 신이 어디 있으리이까 주께서는 죄악과 그 기업에 남은 자의 허물을 사유하시며 인애를 기뻐하시므로 진노를 오래 품지 아니하시나이다"]],"9:20":[[30,"사울이 요나단에게 화를 내며 그에게 이르되 패역무도한 계집의 소생아 네가 이새의 아들을 택한 것이 네 수치와 네 어미의 벌거벗은 수치 됨을 내가 어찌 알지 못하랴"],[31,"이새의 아들이 땅에 사는 동안은 너와 네 나라가 든든히 서지 못하리라 그런즉 이제 사람을 보내어 그를 내게로 끌어 오라 그는 죽어야 할 자이니라 한지라"],[32,"요나단이 그의 아버지 사울에게 대답하여 이르되 그가 죽을 일이 무엇이니이까 무엇을 행하였나이까"],[33,"사울이 요나단에게 단창을 던져 죽이려 한지라 요나단이 그의 아버지가 다윗을 죽이기로 결심한 줄 알고"],[34,"심히 노하여 식탁에서 떠나고 그 달의 둘째 날에는 먹지 아니하였으니 이는 그의 아버지가 다윗을 욕되게 하였으므로 다윗을 위하여 슬퍼함이었더라"],[35,"아침에 요나단이 작은 아이를 데리고 다윗과 정한 시간에 들로 나가서"],[36,"아이에게 이르되 달려가서 내가 쏘는 화살을 찾으라 하고 아이가 달려갈 때에 요나단이 화살을 그의 위로 지나치게 쏘니라"],[37,"아이가 요나단이 쏜 화살 있는 곳에 이를 즈음에 요나단이 아이 뒤에서 외쳐 이르되 화살이 네 앞쪽에 있지 아니하냐 하고"],[38,"요나단이 아이 뒤에서 또 외치되 지체 말고 빨리 달음질하라 하매 요나단의 아이가 화살을 주워 가지고 주인에게로 돌아왔으나"],[39,"그 아이는 아무것도 알지 못하고 요나단과 다윗만 그 일을 알았더라"],[40,"요나단이 그의 무기를 아이에게 주며 이르되 이것을 가지고 성읍으로 가라 하니"],[41,"아이가 가매 다윗이 곧 바위 남쪽에서 일어나서 땅에 엎드려 세 번 절한 후에 서로 입 맞추고 같이 울되 다윗이 더욱 심하더니"],[42,"요나단이 다윗에게 이르되 평안히 가라 우리 두 사람이 여호와의 이름으로 맹세하여 이르기를 여호와께서 영원히 나와 너 사이에 계시고 내 자손과 네 자손 사이에 계시리라 하였느니라 하니 다윗은 일어나 떠나고 요나단은 성읍으로 들어가니라"]],"14:30":[[27,"그 때에 제사장들과 레위 사람들이 일어나서 백성을 위하여 축복하였으니 그 소리가 하늘에 들리고 그 기도가 여호와의 거룩한 처소 하늘에 이르렀더라"]],"30:3":[[2,"내가 땅의 모든 족속 가운데 너희만을 알았나니 그러므로 내가 너희 모든 죄악을 너희에게 보응하리라 하셨나니"]],"10:12":[[3,"가난한 사람은 아무것도 없고 자기가 사서 기르는 작은 암양 새끼 한 마리뿐이라 그 암양 새끼는 그와 그의 자식과 함께 자라며 그가 먹는 것을 먹으며 그의 잔으로 마시며 그의 품에 누우므로 그에게는 딸처럼 되었거늘"],[4,"어떤 행인이 그 부자에게 오매 부자가 자기에게 온 행인을 위하여 자기의 양과 소를 아껴 잡지 아니하고 가난한 사람의 양 새끼를 빼앗아다가 자기에게 온 사람을 위하여 잡았나이다 하니"],[5,"다윗이 그 사람으로 말미암아 노하여 나단에게 이르되 여호와의 살아 계심을 두고 맹세하노니 이 일을 행한 그 사람은 마땅히 죽을 자라"],[6,"그가 불쌍히 여기지 아니하고 이런 일을 행하였으니 그 양 새끼를 네 배나 갚아 주어야 하리라 한지라"],[7,"나단이 다윗에게 이르되 당신이 그 사람이라 이스라엘의 하나님 여호와께서 이와 같이 이르시기를 내가 너를 이스라엘 왕으로 기름 붓기 위하여 너를 사울의 손에서 구원하고"],[15,"나단이 자기 집으로 돌아가니라. 우리아의 아내가 다윗에게 낳은 아이를 여호와께서 치시매 심히 앓는지라"],[16,"다윗이 그 아이를 위하여 하나님께 간구하되 다윗이 금식하고 안에 들어가서 밤새도록 땅에 엎드렸으니"],[17,"그 집의 늙은 자들이 그 곁에 서서 다윗을 땅에서 일으키려 하되 왕이 듣지 아니하고 그들과 더불어 먹지도 아니하더라"],[18,"이레 만에 그 아이가 죽으니라 그러나 다윗의 신하들이 아이가 죽은 것을 왕에게 아뢰기를 두려워하니 이는 그들이 말하기를 아이가 살았을 때에 우리가 그에게 말하여도 왕이 그 말을 듣지 아니하셨나니 어떻게 그 아이가 죽은 것을 그에게 아뢸 수 있으랴 왕이 상심하시리로다 함이라"]],"21:2":[[22,"사람이 해 아래에서 행하는 모든 수고와 마음에 애쓰는 것이 무슨 소득이 있으랴"]],"13:22":[[19,"이제 너희는 마음과 뜻을 바쳐서 너희 하나님 여호와를 구하라 그리고 일어나서 여호와 하나님의 성전을 건축하고 여호와의 언약궤와 하나님 성전의 기물을 가져다가 여호와의 이름을 위하여 건축한 성전에 들이게 하라 하였더라"]],"12:5":[[8,"하나님의 사람 엘리사가 이스라엘 왕이 자기의 옷을 찢었다 함을 듣고 왕에게 보내 이르되 왕이 어찌하여 옷을 찢었나이까 그 사람을 내게로 오게 하소서 그가 이스라엘 중에 선지자가 있는 줄을 알리이다 하니라"],[9,"나아만이 이에 말들과 병거들을 거느리고 이르러 엘리사의 집 문에 서니"],[10,"엘리사가 사자를 그에게 보내 이르되 너는 가서 요단 강에 몸을 일곱 번 씻으라 네 살이 회복되어 깨끗하리라 하는지라"],[11,"나아만이 노하여 물러가며 이르되 내 생각에는 그가 내게로 나와 서서 그의 하나님 여호와의 이름을 부르고 그의 손을 그 부위 위에 흔들어 나병을 고칠까 하였도다"],[12,"다메섹 강 아바나와 바르발은 이스라엘 모든 강물보다 낫지 아니하냐 내가 거기서 몸을 씻으면 깨끗하게 되지 아니하랴 하고 몸을 돌려 분노하여 떠나니"],[13,"그의 종들이 나아와서 말하여 이르되 내 아버지여 선지자가 당신에게 큰 일을 행하라 말하였더면 행하지 아니하였으리이까 하물며 당신에게 이르기를 씻어 깨끗하게 하라 함이리이까 하니"],[14,"나아만이 이에 내려가서 하나님의 사람의 말대로 요단 강에 일곱 번 몸을 잠그니 그의 살이 어린 아이의 살 같이 회복되어 깨끗하게 되었더라"],[26,"엘리사가 이르되 한 사람이 수레에서 내려 너를 맞이할 때에 내 마음이 함께 가지 아니하였느냐 지금이 어찌 은을 받으며 옷을 받으며 감람원이나 포도원이나 양이나 소나 남종이나 여종을 받을 때이냐"]],"14:26":[[18,"웃시야 왕 곁에 서서 그에게 이르되 웃시야여 여호와께 분향하는 일은 왕이 할 바가 아니요 오직 분향하기 위하여 구별함을 받은 아론의 자손 제사장들이 할 바니 성소에서 나가소서 왕이 범죄하였으니 하나님 여호와에게서 영광을 얻지 못하리이다"],[19,"웃시야가 손으로 향로를 잡고 분향하려 하다가 화를 내니 그가 제사장에게 화를 낼 때에 여호와의 전 안 향단 곁 제사장들 앞에서 그의 이마에 나병이 생긴지라"],[20,"대제사장 아사랴와 모든 제사장이 왕의 이마에 나병이 생겼음을 보고 성전에서 급히 쫓아내고 여호와께서 치시므로 왕도 속히 나가니라"]],"23:57":[[13,"네가 부르짖을 때에 네가 모은 우상들에게 너를 구원하게 하라 그것들은 다 바람에 날려 가겠고 기운에 불려갈 것이로되 나를 의뢰하는 자는 땅을 차지하겠고 나의 거룩한 산을 기업으로 얻으리라"],[15,"지극히 존귀하며 영원히 거하시며 거룩하다 이름하는 이가 이와 같이 말씀하시되 내가 높고 거룩한 곳에 있으며 또한 통회하고 마음이 겸손한 자와 함께 있나니 이는 겸손한 자의 영을 소생시키며 통회하는 자의 마음을 소생시키려 함이라"]],"9:21":[[4,"제사장이 다윗에게 대답하여 이르되 보통 떡은 내 수중에 없으나 거룩한 떡은 있나니 그 소년들이 여자를 가까이만 하지 아니하였으면 주리라 하는지라"],[5,"다윗이 제사장에게 대답하여 이르되 우리가 참으로 삼 일 동안이나 여자를 가까이 하지 아니하였나이다 내가 떠난 길이 보통 여행이라도 소년들의 그릇이 성결하겠거든 하물며 오늘 그들의 그릇이 성결하지 아니하겠나이까 하매"]],"10:11":[[11,"우리아가 다윗에게 아뢰되 언약궤와 이스라엘과 유다가 야영 중에 있고 내 주 요압과 내 왕의 부하들이 바깥 들에 진 치고 있거늘 내가 어찌 내 집으로 가서 먹고 마시고 내 처와 같이 자리이까 내가 이 일을 행하지 아니하기로 왕의 살아 계심과 왕의 혼의 살아 계심을 두고 맹세하나이다 하니라"],[25,"다윗이 전령에게 이르되 너는 요압에게 이같이 말하기를 이 일로 걱정하지 말라 칼은 이 사람이나 저 사람이나 삼키느니라 그 성을 향하여 더욱 힘써 싸워 함락시키라 하여 너는 그를 담대하게 하라 하니라"]],"14:1":[[5,"옛적에 훌의 손자 우리의 아들 브살렐이 지은 놋제단은 여호와의 장막 앞에 있더라 솔로몬이 회중과 더불어 나아가서"]],"26:16":[[8,"내가 네 곁으로 지나며 보니 네 때가 사랑을 할 만한 때라 내 옷으로 너를 덮어 벌거벗은 것을 가리고 네게 맹세하고 언약하여 너를 내게 속하게 하였느니라 나 주 여호와의 말이니라"],[13,"이와 같이 네가 금, 은으로 장식하고 가는 베와 모시와 수 놓은 것을 입으며 또 고운 밀가루와 꿀과 기름을 먹음으로 극히 곱고 형통하여 왕후의 지위에 올랐느니라"],[25,"네가 높은 대를 모든 길 어귀에 쌓고 네 아름다움을 가증하게 하여 모든 지나가는 자에게 다리를 벌려 심히 음행하고"]],"33:6":[[6,"내가 무엇을 가지고 여호와 앞에 나아가며 높으신 하나님께 경배할까 내가 번제물로 일 년 된 송아지를 가지고 그 앞에 나아갈까"],[7,"여호와께서 천천의 숫양이나 만만의 강물 같은 기름을 기뻐하실까 내 허물을 위하여 내 맏아들을, 내 영혼의 죄로 말미암아 내 몸의 열매를 드릴까"],[8,"사람아 주께서 선한 것이 무엇임을 네게 보이셨나니 여호와께서 네게 구하시는 것은 오직 정의를 행하며 인자를 사랑하며 겸손하게 네 하나님과 함께 행하는 것이 아니냐"]],"21:3":[[11,"하나님이 모든 것을 지으시되 때를 따라 아름답게 하셨고 또 사람들에게는 영원을 사모하는 마음을 주셨느니라 그러나 하나님이 하시는 일의 시종을 사람으로 측량할 수 없게 하셨도다"]],"24:5":[[6,"그러므로 수풀에서 나오는 사자가 그들을 죽이며 사막의 이리가 그들을 멸하며 표범이 성읍들을 엿본즉 그리로 나오는 자마다 찢기리니 이는 그들의 허물이 많고 반역이 심함이니이다"],[8,"그들은 두루 다니는 살진 수말 같이 각기 이웃의 아내를 따르며 소리지르는도다"],[31,"선지자들은 거짓을 예언하며 제사장들은 자기 권력으로 다스리며 내 백성은 그것을 좋게 여기니 마지막에는 너희가 어찌하려느냐"]],"26:22":[[26,"그 제사장들은 내 율법을 범하였으며 나의 성물을 더럽혔으며 거룩함과 속된 것을 구별하지 아니하였으며 부정함과 정한 것을 사람이 구별하게 하지 아니하였으며 그의 눈을 가리어 나의 안식일을 보지 아니하였으므로 내가 그들 가운데에서 더럽힘을 받았느니라"]],"23:66":[[18,"내가 그들의 행위와 사상을 아노라 때가 이르면 뭇 나라와 언어가 다른 민족들을 모으리니 그들이 와서 나의 영광을 볼 것이며"],[19,"내가 그들 가운데에서 징조를 세워서 그들 가운데에서 도피한 자를 여러 나라 곧 다시스와 뿔과 활을 당기는 룻과 및 두발과 야완과 또 나의 명성을 듣지도 못하고 나의 영광을 보지도 못한 먼 섬들로 보내리니 그들이 나의 영광을 뭇 나라에 전파하리라"],[20,"나 여호와가 말하노라 이스라엘 자손이 예물을 깨끗한 그릇에 담아 여호와의 집에 드림 같이 그들이 너희 모든 형제를 뭇 나라에서 나의 성산 예루살렘으로 말과 수레와 교자와 노새와 낙타에 태워다가 여호와께 예물로 드릴 것이요"],[21,"나는 그 가운데에서 택하여 제사장과 레위인을 삼으리라 여호와의 말이니라"],[22,"내가 지을 새 하늘과 새 땅이 내 앞에 항상 있는 것 같이 너희 자손과 너희 이름이 항상 있으리라 여호와의 말이니라"],[23,"여호와가 말하노라 매월 초하루와 매 안식일에 모든 혈육이 내 앞에 나아와 예배하리라"]],"23:59":[[2,"오직 너희 죄악이 너희와 너희 하나님 사이를 갈라 놓았고 너희 죄가 그의 얼굴을 가리어서 너희에게서 듣지 않으시게 함이니라"],[3,"이는 너희 손이 피에, 너희 손가락이 죄악에 더러워졌으며 너희 입술은 거짓을 말하며 너희 혀는 악독을 냄이라"],[4,"공의대로 소송하는 자도 없고 진실하게 판결하는 자도 없으며 허망한 것을 의뢰하며 거짓을 말하며 악행을 잉태하여 죄악을 낳으며"],[5,"독사의 알을 품으며 거미줄을 짜나니 그 알을 먹는 자는 죽을 것이요 그 알이 밟힌즉 터져서 독사가 나올 것이니라"],[6,"그 짠 것으로는 옷을 이룰 수 없을 것이요 그 행위로는 자기를 가릴 수 없을 것이며 그 행위는 죄악의 행위라 그 손에는 포악한 행동이 있으며"],[7,"그 발은 행악하기에 빠르고 무죄한 피를 흘리기에 신속하며 그 생각은 악한 생각이라 황폐와 파멸이 그 길에 있으며"],[8,"그들은 평강의 길을 알지 못하며 그들이 행하는 곳에는 정의가 없으며 굽은 길을 스스로 만드나니 무릇 이 길을 밟는 자는 평강을 알지 못하느니라"],[9,"그러므로 정의가 우리에게서 멀고 공의가 우리에게 미치지 못한즉 우리가 빛을 바라나 어둠뿐이요 밝은 것을 바라나 캄캄한 가운데에 행하므로"],[10,"우리가 맹인 같이 담을 더듬으며 눈 없는 자 같이 두루 더듬으며 낮에도 황혼 때 같이 넘어지니 우리는 강장한 자 중에서도 죽은 자 같은지라"],[11,"우리가 곰 같이 부르짖으며 비둘기 같이 슬피 울며 정의를 바라나 없고 구원을 바라나 우리에게서 멀도다"],[12,"이는 우리의 허물이 주의 앞에 심히 많으며 우리의 죄가 우리를 쳐서 증언하오니 이는 우리의 허물이 우리와 함께 있음이니라 우리의 죄악을 우리가 아나이다"],[13,"우리가 여호와를 배반하고 속였으며 우리 하나님을 따르는 데에서 돌이켜 포학과 패역을 말하며 거짓말을 마음에 잉태하여 낳으니"],[14,"정의가 뒤로 물리침이 되고 공의가 멀리 섰으며 성실이 거리에 엎드러지고 정직이 나타나지 못하는도다"],[15,"성실이 없어지므로 악을 떠나는 자가 탈취를 당하는도다. 여호와께서 이를 살피시고 그 정의가 없는 것을 기뻐하지 아니하시고"],[16,"사람이 없음을 보시며 중재자가 없음을 이상히 여기셨으므로 자기 팔로 스스로 구원을 베푸시며 자기의 공의를 스스로 의지하사"],[17,"공의를 갑옷으로 삼으시며 구원을 자기의 머리에 써서 투구로 삼으시며 보복을 속옷으로 삼으시며 열심을 입어 겉옷으로 삼으시고"],[18,"그들의 행위대로 갚으시되 그 원수에게 분노하시며 그 원수에게 보응하시며 섬들에게 보복하실 것이라"],[19,"서쪽에서 여호와의 이름을 두려워하겠고 해 돋는 쪽에서 그의 영광을 두려워할 것은 여호와께서 그 기운에 몰려 급히 흐르는 강물 같이 오실 것임이로다"]],"19:19":[[7,"여호와의 율법은 완전하여 영혼을 소성시키며 여호와의 증거는 확실하여 우둔한 자를 지혜롭게 하며"],[8,"여호와의 교훈은 정직하여 마음을 기쁘게 하고 여호와의 계명은 순결하여 눈을 밝게 하시도다"],[9,"여호와를 경외하는 도는 정결하여 영원까지 이르고 여호와의 법도 진실하여 다 의로우니"]],"11:17":[[1,"길르앗에 우거하는 자 중에 디셉 사람 엘리야가 아합에게 말하되 내가 섬기는 이스라엘의 하나님 여호와께서 살아 계심을 두고 맹세하노니 내 말이 없으면 수 년 동안 비도 이슬도 있지 아니하리라 하니라"]],"7:11":[[4,"얼마 후에 암몬 자손이 이스라엘을 치려 하니라"],[5,"암몬 자손이 이스라엘을 치려 할 때에 길르앗 장로들이 입다를 데려오려고 돕 땅에 가서"],[6,"입다에게 이르되 우리가 암몬 자손과 싸우려 하니 당신은 와서 우리의 장관이 되라 하니"],[7,"입다가 길르앗 장로들에게 이르되 너희가 전에 나를 미워하여 내 아버지 집에서 쫓아내지 아니하였느냐 이제 너희가 환난을 당하였다고 어찌하여 내게 왔느냐 하니라"],[8,"그러므로 길르앗 장로들이 입다에게 이르되 이제 우리가 당신을 찾아온 것은 우리와 함께 가서 암몬 자손과 싸우게 하려 함이니 그리하면 당신이 우리 길르앗 모든 주민의 머리가 되리라 하매"],[9,"입다가 길르앗 장로들에게 이르되 너희가 나를 데리고 고향으로 돌아가서 암몬 자손과 싸우게 할 때에 만일 여호와께서 그들을 내게 넘겨 주시면 내가 과연 너희의 머리가 되겠느냐 하니"],[10,"길르앗 장로들이 입다에게 이르되 여호와는 우리 사이의 증인이시니 당신의 말대로 우리가 그렇게 행하리이다 하니라"],[11,"이에 입다가 길르앗 장로들과 함께 가니 백성이 그를 자기들의 머리와 장관을 삼은지라 입다가 미스바에서 자기의 말을 다 여호와 앞에 아뢰니라"],[12,"입다가 암몬 자손의 왕에게 사자들을 보내 이르되 네가 나와 무슨 상관이 있기에 내 땅을 치러 내게 왔느냐 하니"],[13,"암몬 자손의 왕이 입다의 사자들에게 대답하되 이스라엘이 애굽에서 올라올 때에 아르논에서부터 얍복과 요단까지 내 땅을 점령했기 때문이니 이제 그것을 평화롭게 돌려 달라 하니라"],[14,"입다가 암몬 자손의 왕에게 다시 사자들을 보내"],[15,"그에게 이르되 입다가 이같이 말하노라 이스라엘이 모압 땅과 암몬 자손의 땅을 점령하지 아니하였느니라"],[16,"이스라엘이 애굽에서 올라올 때에 광야로 행하여 홍해에 이르고 가데스에 이르러서는"],[17,"이스라엘이 사자들을 에돔 왕에게 보내어 이르기를 청하건대 나를 네 땅 가운데로 지나게 하라 하였으나 에돔 왕이 이를 듣지 아니하였고 또 그와 같이 사람을 모압 왕에게도 보냈으나 그도 허락하지 아니하므로 이스라엘이 가데스에 머물렀더니"],[18,"그 후에 광야를 지나 에돔 땅과 모압 땅을 돌아서 모압 땅의 해 뜨는 쪽으로 들어가 아르논 저쪽에 진 쳤고 아르논은 모압의 경계이므로 모압 지역 안에는 들어가지 아니하였으며"],[19,"이스라엘이 헤스본 왕 곧 아모리 족속의 왕 시혼에게 사자들을 보내어 그에게 이르되 청하건대 우리를 당신의 땅으로 지나 우리의 곳에 이르게 하라 하였으나"],[20,"시혼이 이스라엘을 믿지 아니하여 그의 지역으로 지나지 못하게 할 뿐 아니라 그의 모든 백성을 모아 야하스에 진 치고 이스라엘을 치므로"],[21,"이스라엘의 하나님 여호와께서 시혼과 그의 모든 백성을 이스라엘의 손에 넘겨 주시매 이스라엘이 그들을 쳐서 그 땅 주민 아모리 족속의 온 땅을 점령하되"],[22,"아르논에서부터 얍복까지와 광야에서부터 요단까지 아모리 족속의 온 지역을 점령하였느니라"],[23,"이스라엘의 하나님 여호와께서 이같이 아모리 족속을 자기 백성 이스라엘 앞에서 쫓아내셨거늘 네가 그 땅을 얻고자 하는 것이 옳으냐"],[24,"네 신 그모스가 네게 주어 차지하게 한 것을 네가 차지하지 아니하겠느냐 우리 하나님 여호와께서 우리 앞에서 어떤 사람이든지 쫓아내시면 그것을 우리가 차지하리라"],[25,"이제 네가 모압 왕 십볼의 아들 발락보다 더 나은 것이 있느냐 그가 이스라엘과 더불어 다툰 일이 있었느냐 싸운 일이 있었느냐"],[26,"이스라엘이 헤스본과 그 마을들과 아로엘과 그 마을들과 아르논 강 가에 있는 모든 성읍에 거주한 지 삼백 년이거늘 그 동안에 너희가 어찌하여 도로 찾지 아니하였느냐"],[27,"내가 네게 죄를 짓지 아니하였거늘 네가 나를 쳐서 내게 악을 행하고자 하는도다 원하건대 심판하시는 여호와께서 오늘 이스라엘 자손과 암몬 자손 사이에 판결하시옵소서 하였으나"],[28,"암몬 자손의 왕이 입다가 사람을 보내어 말한 것을 듣지 아니하였더라"],[29,"이에 여호와의 영이 입다에게 임하시니 입다가 길르앗과 므낫세를 지나서 길르앗의 미스베에 이르고 길르앗의 미스베에서부터 암몬 자손에게로 나아갈 때에"],[30,"그가 여호와께 서원하여 이르되 주께서 과연 암몬 자손을 내 손에 넘겨 주시면"],[31,"내가 암몬 자손에게서 평안히 돌아올 때에 누구든지 내 집 문에서 나와서 나를 영접하는 그는 여호와께 돌릴 것이니 내가 그를 번제물로 드리겠나이다 하니라"],[32,"이에 입다가 암몬 자손에게 이르러 그들과 싸우더니 여호와께서 그들을 그의 손에 넘겨 주시매"],[33,"아로엘에서부터 민닛에 이르기까지 이십 성읍을 치고 또 아벨 그라밈까지 매우 크게 무찌르니 이에 암몬 자손이 이스라엘 자손 앞에 항복하였더라"]],"19:66":[[13,"내가 번제물을 가지고 주의 집에 들어가서 나의 서원을 주께 갚으리니"],[14,"이는 내 입술이 낸 것이요 내 환난 때에 내 입이 말한 것이니이다"]],"6:1":[[5,"네 평생에 너를 능히 대적할 자가 없으리니 내가 모세와 함께 있었던 것 같이 너와 함께 있을 것임이니라 내가 너를 떠나지 아니하며 버리지 아니하리니"],[8,"이 율법책을 네 입에서 떠나지 말게 하며 주야로 그것을 묵상하여 그 안에 기록된 대로 다 지켜 행하라 그리하면 네 길이 평탄하게 될 것이며 네가 형통하리라"],[9,"내가 네게 명령한 것이 아니냐 강하고 담대하라 두려워하지 말며 놀라지 말라 네가 어디로 가든지 네 하나님 여호와가 너와 함께 하느니라 하시니라"]],"7:1":[[1,"여호수아가 죽은 후에 이스라엘 자손이 여호와께 여쭈어 이르되 우리 가운데 누가 먼저 올라가서 가나안 족속과 싸우리이까"]],"13:5":[[9,"또 동으로 가서 거주하면서 유브라데 강에서부터 광야 지경까지 다다랐으니 이는 길르앗 땅에서 그 가축이 번식함이라"],[18,"르우벤 자손과 갓 사람과 므낫세 반 지파에서 나가 싸울 만한 용사 곧 능히 방패와 칼을 들며 활을 당겨 싸움에 익숙한 자는 사만 사천칠백육십 명이라"],[25,"그들이 그들의 조상들의 하나님께 범죄하여 하나님이 그들 앞에서 멸하신 그 땅 백성의 신들을 간음하듯 섬긴지라"],[26,"그러므로 이스라엘 하나님이 앗수르 왕 불의 마음을 일으키시며 앗수르 왕 디글랏 빌레셀의 마음을 일으키시매 곧 르우벤과 갓과 므낫세 반 지파를 사로잡아 할라와 하볼과 하라와 고산 강 가에 옮긴지라 그들이 오늘까지 거기에 있으니라"]],"26:27":[[27,"네 재물과 상품과 바꾼 물건과 네 사공과 선장과 네 배의 틈을 막는 자와 네 상인과 네 가운데에 있는 모든 용사와 네 가운데에 있는 모든 무리가 네가 패망하는 날에 다 바다 한가운데에 빠질 것임이여"]],"19:74":[[4,"주의 대적이 주의 회중 가운데에서 떠들며 자기들의 깃발을 세워 표적으로 삼았으니"]],"12:18":[[4,"그가 여러 산당들을 제거하며 주상을 깨뜨리며 아세라 목상을 찍으며 모세가 만들었던 놋뱀을 이스라엘 자손이 이때까지 향하여 분향하므로 그것을 부수고 느후스단이라 일컬었더라"],[25,"내가 어찌 여호와의 뜻이 아니고야 이제 이 곳을 멸하러 올라왔겠느냐 여호와께서 전에 내게 이르시기를 이 땅으로 올라와서 쳐서 멸하라 하셨느니라 하는지라"]],"26:23":[[6,"그들은 다 자색 옷을 입은 고관과 감독이요 준수한 청년이요 말 타는 자들이라"]],"20:12":[[10,"의인은 자기의 가축의 생명을 돌보나 악인의 긍휼은 잔인이니라"]],"23:35":[[8,"거기에 대로가 있어 그 길을 거룩한 길이라 일컫는 바 되리니 깨끗하지 못한 자는 지나가지 못하겠고 오직 구속함을 입은 자들을 위하여 있게 될 것이라 우매한 행인은 그 길로 다니지 못할 것이며"],[9,"거기에는 사자가 없고 사나운 짐승이 그리로 올라가지 아니하므로 그것을 만나지 못하겠고 오직 구속함을 받은 자만 그리로 행할 것이며"],[10,"여호와의 속량함을 받은 자들이 돌아오되 노래하며 시온에 이르러 그들의 머리 위에 영영한 희락을 띠고 기쁨과 즐거움을 얻으리니 슬픔과 탄식이 사라지리로다"]],"23:28":[[7,"그리하여도 이들은 포도주로 말미암아 옆 걸음 치며 독주로 말미암아 비틀거리며 제사장과 선지자도 독주로 말미암아 옆 걸음 치며 포도주에 빠지며 독주로 말미암아 비틀거리며 환상을 잘못 풀며 재판할 때에 실수하나니"],[29,"이도 만군의 여호와께로부터 난 것이라 그의 경영은 기묘하며 지혜는 광대하니라"]],"30:2":[[10,"내가 너희를 애굽 땅에서 이끌어 내어 사십 년 동안 광야에서 인도하고 아모리 사람의 땅을 너희가 차지하게 하였고"],[12,"그러나 너희가 나실 사람으로 포도주를 마시게 하며 또 선지자에게 명령하여 예언하지 말라 하였느니라"]],"19:122":[[1,"사람이 내게 말하기를 여호와의 집에 올라가자 할 때에 내가 기뻐하였도다"]],"13:15":[[24,"제사장 스바냐와 요사밧과 느다넬과 아미새와 스가랴와 브나야와 엘리에셀은 하나님의 궤 앞에서 나팔을 부는 자요 오벧에돔과 여히야는 궤 앞에서 문을 지키는 자이더라"]],"14:5":[[12,"노래하는 레위 사람 아삽과 헤만과 여두둔과 그의 아들들과 형제들이 다 세마포를 입고 제단 동쪽에 서서 제금과 비파와 수금을 잡고 또 나팔 부는 제사장 백이십 명이 함께 서 있다가"]],"19:16":[[4,"다른 신에게 예물을 드리는 자는 괴로움이 더할 것이라 나는 그들이 드리는 피의 전제를 드리지 아니하며 내 입술로 그 이름도 부르지 아니하리로다"],[5,"여호와는 나의 산업과 나의 잔의 소득이시니 나의 분깃을 지키시나이다"],[6,"내게 줄로 재어 준 구역은 아름다운 곳에 있음이여 나의 기업이 실로 아름답도다"],[11,"주께서 생명의 길을 내게 보이시리니 주의 앞에는 충만한 기쁨이 있고 주의 오른쪽에는 영원한 즐거움이 있나이다"]],"23:50":[[2,"내가 왔어도 사람이 없었으며 내가 불러도 대답하는 자가 없었음은 어찌 됨이냐 내 손이 어찌 짧아 구속하지 못하겠느냐 내게 어찌 건질 능력이 없겠느냐 보라 내가 꾸짖어 바다를 마르게 하며 강들을 사막이 되게 하며 물이 없어졌으므로 그 물고기들이 악취를 내며 갈하여 죽으리라"],[6,"나를 때리는 자들에게 내 등을 맡기며 나의 수염을 뽑는 자들에게 나의 뺨을 맡기며 모욕과 침 뱉음을 당하여도 내 얼굴을 가리지 아니하였느니라"]],"24:32":[[17,"슬프도소이다 주 여호와여 주께서 큰 능력과 펴신 팔로 천지를 지으셨사오니 주에게는 할 수 없는 일이 없으시니이다"]],"47:10":[[3,"우리가 육신으로 행하나 육신에 따라 싸우지 아니하노니"],[4,"우리의 싸우는 무기는 육신에 속한 것이 아니요 오직 어떤 견고한 진도 무너뜨리는 하나님의 능력이라 모든 이론을 무너뜨리며"],[5,"하나님 아는 것을 대적하여 높아진 것을 다 무너뜨리고 모든 생각을 사로잡아 그리스도에게 복종하게 하니"],[6,"너희의 복종이 온전하게 될 때에 모든 복종하지 않는 것을 벌하려고 준비하는 중에 있노라"]],"19:69":[[32,"곤고한 자가 이를 보고 기뻐하나니 하나님을 찾는 너희들아 너희 마음을 소생하게 할지어다"]],"36:2":[[3,"여호와의 규례를 지키는 세상의 모든 겸손한 자들아 너희는 여호와를 찾으며 공의와 겸손을 구하라 너희가 혹시 여호와의 분노의 날에 숨김을 얻으리라"]],"18:30":[[10,"그들이 나를 미워하여 멀리 하고 서슴지 않고 내 얼굴에 침을 뱉는도다"]],"43:9":[[39,"예수께서 이르시되 내가 심판하러 이 세상에 왔으니 보지 못하는 자들은 보게 하고 보는 자들은 맹인이 되게 하려 함이라 하시니"],[40,"바리새인 중에 예수와 함께 있던 자들이 이 말씀을 듣고 이르되 우리도 맹인인가"],[41,"예수께서 이르시되 너희가 맹인이 되었더라면 죄가 없으려니와 본다고 하니 너희 죄가 그대로 있느니라"]],"9:13":[[8,"사울은 사무엘이 정한 기한대로 이레 동안을 기다렸으나 사무엘이 길갈로 오지 아니하매 백성이 사울에게서 흩어지는지라"],[9,"사울이 이르되 번제와 화목제물을 이리로 가져오라 하여 번제를 드렸더니"],[10,"번제 드리기를 마치자 사무엘이 온지라 사울이 나가 맞으며 문안하매"],[11,"사무엘이 이르되 왕이 행하신 것이 무엇이냐 하니 사울이 이르되 백성은 내게서 흩어지고 당신은 정한 날 안에 오지 아니하고 블레셋 사람은 믹마스에 모였음을 내가 보았으므로"],[12,"이에 내가 이르기를 블레셋 사람들이 나를 치러 길갈로 내려오겠거늘 내가 여호와께 은혜를 간구하지 못하였다 하고 부득이하여 번제를 드렸나이다 하니라"],[13,"사무엘이 사울에게 이르되 왕이 망령되이 행하였도다 왕이 왕의 하나님 여호와께서 왕에게 내리신 명령을 지키지 아니하였도다 그리하였더라면 여호와께서 이스라엘 위에 왕의 나라를 영원히 세우셨을 것이거늘"],[14,"지금은 왕의 나라가 길지 못할 것이라 여호와께서 왕에게 명령하신 바를 왕이 지키지 아니하였으므로 여호와께서 그의 마음에 맞는 사람을 구하여 여호와께서 그를 그의 백성의 지도자로 삼으셨느니라 하고"]],"37:2":[[12,"사람이 옷자락에 거룩한 고기를 쌌는데 그 옷자락이 만일 떡에나 국에나 포도주에나 기름에나 다른 음식물에 닿았으면 그것이 성물이 되겠느냐 하라 학개가 물으매 제사장들이 대답하여 이르되 아니니라 하는지라"],[13,"학개가 이르되 시체를 만져서 부정하여진 자가 만일 그것들 가운데 하나를 만지면 그것이 부정하겠느냐 하니 제사장들이 대답하여 이르되 부정하리라 하더라"],[14,"이에 학개가 대답하여 이르되 여호와의 말씀에 내 앞에서 이 백성이 그러하고 이 나라가 그러하고 그들의 손의 모든 일도 그러하고 그들이 거기에서 드리는 것도 부정하니라"]],"23:46":[[8,"너희 패역한 자들아 이 일을 기억하고 장부가 되라 이 일을 마음에 두라"],[12,"마음이 완악하여 공의에서 멀리 떠난 너희여 내게 들으라"]],"19:42":[[1,"하나님이여 사슴이 시냇물을 찾기에 갈급함 같이 내 영혼이 주를 찾기에 갈급하니이다"]],"18:27":[[3,"(나의 호흡이 아직 내 속에 완전히 있고 하나님의 숨결이 아직도 내 코에 있느니라)"]],"7:5":[[16,"네가 양의 우리 가운데에 앉아서 목자의 피리 부는 소리를 들음은 어찌 됨이냐 르우벤 시냇가에서 큰 결심이 있었도다"]],"23:11":[[1,"이새의 줄기에서 한 싹이 나며 그 뿌리에서 한 가지가 나서 결실할 것이요"],[2,"그의 위에 여호와의 영 곧 지혜와 총명의 영이요 모략과 재능의 영이요 지식과 여호와를 경외하는 영이 강림하시리니"],[3,"그가 여호와를 경외함으로 즐거움을 삼을 것이며 그의 눈에 보이는 대로 심판하지 아니하며 그의 귀에 들리는 대로 판단하지 아니하며"],[4,"공의로 가난한 자를 심판하며 정직으로 세상의 겸손한 자를 판단할 것이며 그의 입의 막대기로 세상을 치며 그의 입술의 기운으로 악인을 죽일 것이며"],[5,"공의로 그의 허리띠를 삼으며 성실로 그의 몸의 띠를 삼으리라"],[10,"그 날에 이새의 뿌리에서 한 싹이 나서 만민의 기치로 설 것이요 열방이 그에게로 돌아오리니 그가 거한 곳이 영화로우리라"]],"9:27":[[1,"다윗이 그 마음에 생각하기를 내가 후일에는 사울의 손에 붙잡히리니 블레셋 사람들의 땅으로 피하여 들어가는 것이 좋으리로다 사울이 이스라엘 온 영토 내에서 다시 나를 찾다가 단념하리니 내가 그의 손에서 벗어나리라 하고"]],"19:56":[[3,"내가 두려워하는 날에는 내가 주를 의지하리이다"]],"10:16":[[5,"다윗 왕이 바후림에 이르매 거기서 사울의 친족 한 사람이 나오니 게라의 아들이요 이름은 시므이라 그가 나오면서 계속하여 저주하고"]],"6:5":[[1,"요단 서쪽의 아모리 사람의 모든 왕들과 해변의 가나안 사람의 모든 왕들이 여호와께서 요단 물을 이스라엘 자손들 앞에서 말리시고 우리를 건너게 하셨음을 듣고 마음이 녹았고 이스라엘 자손들 때문에 정신을 잃었더라"],[6,"이스라엘 자손들이 여호와의 음성을 청종하지 아니하므로 여호와께서 그들에게 대하여 맹세하사 그들의 조상들에게 맹세하여 우리에게 주리라고 하신 땅 곧 젖과 꿀이 흐르는 땅을 그들이 보지 못하게 하리라 하시매 애굽에서 나온 족속 곧 군사들이 다 멸절하기까지 사십 년 동안을 광야에서 헤매었더니"],[7,"그들의 대를 잇게 하신 이 자손에게 여호수아가 할례를 행하였으니 길에서는 그들에게 할례를 행하지 못하였으므로 할례 없는 자가 되었음이었더라"],[8,"또 그 모든 백성에게 할례 행하기를 마치매 백성이 진중 각 처소에 머물며 낫기를 기다릴 때에"],[9,"여호와께서 여호수아에게 이르시되 내가 오늘 애굽의 수치를 너희에게서 떠나가게 하였다 하셨으므로 그 곳 이름을 오늘까지 길갈이라 하느니라"],[10,"또 이스라엘 자손들이 길갈에 진 쳤고 그 달 십사일 저녁에는 여리고 평지에서 유월절을 지켰으며"],[11,"유월절 이튿날에 그 땅의 소산물을 먹되 그 날에 무교병과 볶은 곡식을 먹었더라"],[12,"또 그 땅의 소산물을 먹은 다음 날에 만나가 그쳤으니 이스라엘 사람들이 다시는 만나를 얻지 못하였고 그 해에 가나안 땅의 소출을 먹었더라"],[13,"여호수아가 여리고에 가까이 이르렀을 때에 눈을 들어 본즉 한 사람이 칼을 빼어 손에 들고 마주 서 있는지라 여호수아가 나아가서 그에게 묻되 너는 우리를 위하느냐 우리의 적들을 위하느냐 하니"]],"9:5":[[1,"블레셋 사람들이 하나님의 궤를 빼앗아 가지고 에벤에셀에서부터 아스돗에 이르니라"],[2,"블레셋 사람들이 하나님의 궤를 가지고 다곤의 신전에 들어가서 다곤 곁에 두었더니"],[3,"아스돗 사람들이 이튿날 일찍이 일어나 본즉 다곤이 여호와의 궤 앞에서 엎드러져 그 얼굴이 땅에 닿았는지라 그들이 다곤을 일으켜 다시 그 자리에 세웠더니"],[4,"그 이튿날 아침에 그들이 일찍이 일어나 본즉 다곤이 여호와의 궤 앞에서 또다시 엎드러져 얼굴이 땅에 닿았고 그 머리와 두 손목은 끊어져 문지방에 있고 다곤의 몸뚱이만 남았더라"],[5,"그러므로 다곤의 제사장들이나 다곤의 신전에 들어가는 자는 오늘까지 아스돗에 있는 다곤의 문지방을 밟지 아니하더라"],[6,"여호와의 손이 아스돗 사람에게 엄중히 더하사 독한 종기의 재앙으로 아스돗과 그 지역을 쳐서 망하게 하니"]],"9:19":[[23,"사울이 라마 나욧으로 가니라 하나님의 영이 그에게도 임하시니 그가 라마 나욧에 이르기까지 걸어가며 예언을 하였으며"]],"30:5":[[14,"너희는 살려면 선을 구하고 악을 구하지 말지어다 만군의 하나님 여호와께서 너희의 말과 같이 너희와 함께 하시리라"],[15,"너희는 악을 미워하고 선을 사랑하며 성문에서 정의를 세울지어다 만군의 하나님 여호와께서 혹시 요셉의 남은 자를 불쌍히 여기시리라"],[22,"너희가 내게 번제나 소제를 드릴지라도 내가 받지 아니할 것이요 너희의 살진 희생의 화목제도 내가 돌아보지 아니하리라"]],"19:1":[[1,"복 있는 사람은 악인들의 꾀를 따르지 아니하며 죄인들의 길에 서지 아니하며 오만한 자들의 자리에 앉지 아니하고"],[3,"그는 시냇가에 심은 나무가 철을 따라 열매를 맺으며 그 잎사귀가 마르지 아니함 같으니 그가 하는 모든 일이 다 형통하리로다"]],"24:30":[[3,"여호와의 말씀이니라 보라 내가 내 백성 이스라엘과 유다의 포로를 돌아가게 할 날이 오리니 내가 그들을 그 조상들에게 준 땅으로 돌아오게 할 것이니 그들이 그 땅을 차지하리라 여호와께서 말씀하시니라"],[9,"그들은 그들의 하나님 여호와를 섬기며 내가 그들을 위하여 세울 그들의 왕 다윗을 섬기리라"]],"26:34":[[24,"나 여호와는 그들의 하나님이 되고 내 종 다윗은 그들 중에 왕이 되리라 나 여호와의 말이니라"]],"28:3":[[5,"그 후에 이스라엘 자손이 돌아와서 그들의 하나님 여호와와 그들의 왕 다윗을 찾고 마지막 날에는 여호와를 경외하므로 여호와와 그의 은총으로 나아가리라"]],"11:14":[[23,"이는 그들도 산 위에와 모든 푸른 나무 아래에 산당과 우상과 아세라 상을 세웠음이라"]],"12:17":[[10,"모든 산 위에와 모든 푸른 나무 아래에 목상과 아세라 상을 세우고"]],"16:13":[[29,"내 하나님이여 그들이 제사장의 직분을 더럽히고 제사장의 직분과 레위 사람에 대한 언약을 어겼사오니 그들을 기억하옵소서"]],"19:28":[[8,"여호와는 그들의 힘이시요 그의 기름 부음 받은 자의 구원의 요새이시로다"],[9,"주의 백성을 구원하시며 주의 산업에 복을 주시고 또 그들의 목자가 되시어 영원토록 그들을 인도하소서"]],"36:3":[[4,"그의 선지자들은 경솔하고 간사한 사람들이요 그의 제사장들은 성소를 더럽히고 율법을 범하였도다"]],"19:89":[[2,"내가 말하기를 인자하심을 영원히 세우시며 주의 성실하심을 하늘에서 견고히 하시리라 하였나이다"],[31,"내 율례를 깨뜨리며 내 계명을 지키지 아니하면"],[48,"누가 살아서 죽음을 보지 아니하고 자기의 영혼을 스올의 권세에서 건지리이까 (셀라)"]],"23:19":[[1,"애굽에 관한 경고라. 보라 여호와께서 빠른 구름을 타고 애굽에 임하시리니 애굽의 우상들이 그 앞에서 떨겠고 애굽인의 마음이 그 속에서 녹으리로다"],[21,"여호와께서 자기를 애굽에 알게 하시리니 그 날에 애굽이 여호와를 알고 제물과 예물을 그에게 드리고 경배할 것이요 여호와께 서원하고 그대로 행하리라"],[22,"여호와께서 애굽을 치실지라도 치시고는 고치실 것이므로 그들이 여호와께로 돌아올 것이라 여호와께서 그들의 간구함을 들으시고 그들을 고쳐 주시리라"]],"19:35":[[13,"나는 그들이 병 들었을 때에 굵은 베 옷을 입으며 금식하여 내 영혼을 괴롭게 하였더니 내 기도가 내 품으로 돌아왔도다"]],"23:58":[[3,"우리가 금식하되 어찌하여 주께서 보지 아니하시오며 우리가 마음을 괴롭게 하되 어찌하여 주께서 알아 주지 아니하시나이까 보라 너희가 금식하는 날에 오락을 구하며 온갖 일을 시키는도다"]],"19:15":[[1,"여호와여 주의 장막에 머무를 자 누구오며 주의 성산에 사는 자 누구오니이까"],[4,"그의 눈은 망령된 자를 멸시하며 여호와를 두려워하는 자들을 존대하며 그의 마음에 서원한 것은 해로울지라도 변하지 아니하며"]],"20:20":[[25,"함부로 이 물건은 거룩하다 하여 서원하고 그 후에 살피면 그것이 그 사람에게 덫이 되느니라"]],"19:149":[[7,"이것으로 뭇 나라에 보수하며 민족들을 벌하며"],[8,"그들의 왕들은 사슬로, 그들의 귀인은 철고랑으로 결박하고"],[9,"기록한 판결대로 그들에게 시행할지로다 이런 영광은 그의 모든 성도에게 있도다 할렐루야"]],"23:34":[[8,"이것은 여호와께서 보복하시는 날이요 시온의 송사를 위하여 신원하시는 해라"]],"23:44":[[22,"내가 네 허물을 빽빽한 구름 같이, 네 죄를 안개 같이 없이하였으니 너는 내게로 돌아오라 내가 너를 구속하였음이니라"]],"10:13":[[13,"내가 이 수치를 지니고 어디로 가겠느냐 너도 이스라엘에서 어리석은 자 중의 하나가 되리라 이제 청하건대 왕께 말하라 그가 나를 네게 주기를 거절하지 아니하시리라 하되"]],"6:13":[[20,"벳브올과 비스가 산기슭과 벧여시못과"],[21,"평지 모든 성읍과 헤스본에서 다스리던 아모리 족속의 왕 시혼의 온 나라라 모세가 시혼을 그 땅에 거주하는 시혼의 군주들 곧 미디안의 귀족 에위와 레겜과 술과 훌과 레바와 함께 죽였으며"]],"26:30":[[13,"주 여호와께서 이같이 말씀하셨느니라 내가 그 우상들을 없애며 신상들을 놉 가운데에서 부수며 애굽 땅에서 왕이 다시 나지 못하게 하고 그 땅에 두려움이 있게 하리라"]],"39:2":[[6,"그의 입에는 진리의 법이 있었고 그의 입술에는 불의함이 없었으며 그가 화평함과 정직함으로 나와 동행하며 많은 사람을 돌이켜 죄악에서 떠나게 하였느니라"],[7,"제사장의 입술은 지식을 지켜야 하겠고 사람들은 그의 입에서 율법을 구하게 되어야 할 것이니 제사장은 만군의 여호와의 사자가 됨이거늘"],[16,"이스라엘의 하나님 여호와가 이르노니 나는 이혼하는 것과 옷으로 학대를 가리는 자를 미워하노라 만군의 여호와의 말이니라 그러므로 너희 심령을 삼가 지켜 거짓을 행하지 말지니라"]],"6:21":[[1,"그 때에 레위 사람의 족장들이 제사장 엘르아살과 눈의 아들 여호수아와 이스라엘 자손의 지파 족장들에게 나아와"],[2,"가나안 땅 실로에서 그들에게 말하여 이르되 여호와께서 모세에게 명령하사 우리가 거주할 성읍들과 우리 가축을 위해 그 목초지들을 우리에게 주라 하셨나이다 하매"],[3,"이스라엘 자손이 여호와의 명령을 따라 자기의 기업에서 이 성읍들과 그 목초지들을 레위 사람에게 주니라"],[4,"그핫 가족을 위하여 제비를 뽑았는데 레위 사람 중 제사장 아론의 자손들은 유다 지파와 시므온 지파와 베냐민 지파 중에서 제비 뽑은 대로 열세 성읍을 받았고"],[5,"그핫 자손들 중에 남은 자는 에브라임 지파의 가족과 단 지파와 므낫세 반 지파 중에서 제비 뽑은 대로 열 성읍을 받았으며"],[6,"게르손 자손들은 잇사갈 지파의 가족들과 아셀 지파와 납달리 지파와 바산에 있는 므낫세 반 지파 중에서 제비 뽑은 대로 열세 성읍을 받았더라"],[7,"므라리 자손들은 그 가족대로 르우벤 지파와 갓 지파와 스불론 지파 중에서 열두 성읍을 받았더라"],[8,"여호와께서 모세에게 명령하신 대로 이스라엘 자손이 제비 뽑아 레위 사람에게 준 성읍들과 그 목초지들이 이러하니라"],[9,"유다 자손의 지파와 시므온 자손의 지파 중에서는 이 아래에 기명한 성읍들을 주었는데"],[10,"레위 자손 중 그핫 가족들에 속한 아론 자손이 첫째로 제비 뽑혔으므로"],[11,"아낙의 아버지 아르바의 성읍 유다 산지 기럇 아르바 곧 헤브론과 그 주위의 목초지를 그들에게 주었고"],[12,"그 성읍의 밭과 그 촌락들은 여분네의 아들 갈렙에게 주어 소유가 되게 하였더라"],[13,"제사장 아론의 자손에게 준 것은 살인자의 도피성 헤브론과 그 목초지이요 또 립나와 그 목초지와"],[14,"얏딜과 그 목초지와 에스드모아와 그 목초지와"],[15,"홀론과 그 목초지와 드빌과 그 목초지와"],[16,"아인과 그 목초지와 윳다와 그 목초지와 벧 세메스와 그 목초지이니 이 두 지파에서 아홉 성읍을 냈고"],[17,"또 베냐민 지파 중에서는 기브온과 그 목초지와 게바와 그 목초지와"],[18,"아나돗과 그 목초지와 알몬과 그 목초지 곧 네 성읍을 냈으니"],[19,"제사장 아론 자손의 성읍은 모두 열세 성읍과 그 목초지들이었더라"],[20,"레위 사람인 그핫 자손 중에 남은 자들의 가족들 곧 그핫 자손에게는 제비 뽑아 에브라임 지파 중에서 그 성읍들을 주었으니"],[21,"곧 살인자의 도피성 에브라임 산지 세겜과 그 목초지이요 또 게셀과 그 목초지와"],[22,"깁사임과 그 목초지와 벧 호론과 그 목초지이니 네 성읍이요"],[23,"또 단 지파 중에서 준 것은 엘드게와 그 목초지와 깁브돈과 그 목초지와"],[24,"아얄론과 그 목초지와 가드 림몬과 그 목초지이니 네 성읍이요"],[25,"또 므낫세 반 지파 중에서 준 것은 다아낙과 그 목초지와 가드 림몬과 그 목초지이니 두 성읍이라"],[26,"그핫 자손의 남은 가족들을 위한 성읍들은 모두 열 성읍과 그 목초지들이었더라"],[27,"레위 가족의 게르손 자손에게는 므낫세 반 지파 중에서 살인자의 도피성 바산 골란과 그 목초지를 주었고 또 브에스드라와 그 목초지를 주었으니 두 성읍이요"],[28,"잇사갈 지파 중에서는 기시온과 그 목초지와 다브랏과 그 목초지와"],[29,"야르뭇과 그 목초지와 엔 간님과 그 목초지를 주었으니 네 성읍이요"],[30,"아셀 지파 중에서는 미살과 그 목초지와 압돈과 그 목초지와"],[31,"헬갓과 그 목초지와 르홉과 그 목초지를 주었으니 네 성읍이요"],[32,"납달리 지파 중에서는 살인자의 도피성 갈릴리 게데스와 그 목초지를 주었고 또 함못 돌과 그 목초지와 가르단과 그 목초지를 주었으니 세 성읍이라"],[33,"게르손 사람이 그 가족대로 받은 성읍은 모두 열세 성읍과 그 목초지들이었더라"],[34,"그 남은 레위 사람 므라리 자손의 가족들에게 준 것은 스불론 지파 중에서 욕느암과 그 목초지와 가르다와 그 목초지와"],[35,"딤나와 그 목초지와 나할랄과 그 목초지이니 네 성읍이요"],[36,"르우벤 지파 중에서 준 것은 베셀과 그 목초지와 야하스와 그 목초지와"],[37,"그데못과 그 목초지와 므바앗과 그 목초지이니 네 성읍이요"],[38,"갓 지파 중에서 준 것은 살인자의 도피성 길르앗 라못과 그 목초지이요 또 마하나임과 그 목초지와"],[39,"헤스본과 그 목초지와 야셀과 그 목초지이니 모두 네 성읍이라"],[40,"이는 레위 가족의 남은 자 곧 므라리 자손이 그들의 가족대로 받은 성읍이니 그들이 제비 뽑아 얻은 성읍이 열두 성읍이었더라"],[41,"레위 사람들이 이스라엘 자손의 기업 중에서 받은 성읍은 모두 마흔여덟 성읍이요 또 그 목초지들이라"],[42,"이 각 성읍의 주위에 목초지가 있었고 모든 성읍이 다 그러하였더라"],[45,"여호와께서 이스라엘 족속에게 말씀하신 선한 말씀이 하나도 남음이 없이 다 응하였더라"]],"6:14":[[6,"그 때에 유다 자손이 길갈에 있는 여호수아에게 나아오고 그니스 사람 여분네의 아들 갈렙이 여호수아에게 말하되 여호와께서 가데스 바네아에서 나와 당신에게 대하여 하나님의 사람 모세에게 이르신 일을 당신이 아시는 바라"],[7,"내 나이 사십 세에 여호와의 종 모세가 가데스 바네아에서 나를 보내어 이 땅을 정탐하게 하였으므로 내가 성실한 마음으로 그에게 보고하였고"],[8,"나와 함께 올라갔던 내 형제들은 백성의 간담을 녹게 하였으나 나는 내 하나님 여호와께 충성하였으므로"],[9,"그 날에 모세가 맹세하여 이르되 네가 내 하나님 여호와께 충성하였은즉 네 발로 밟는 땅은 영원히 너와 네 자손의 기업이 되리라 하였나이다"],[10,"이제 보소서 여호와께서 이 말씀을 모세에게 이르신 때로부터 이스라엘이 광야에서 방황한 이 사십오 년 동안을 여호와께서 말씀하신 대로 나를 생존하게 하셨나이다 오늘 내가 팔십오 세로되"],[11,"모세가 나를 보내던 날과 같이 오늘도 내가 여전히 강건하니 내 힘이 그 때나 지금이나 같아서 싸움에나 출입에 감당할 수 있으니"],[12,"그 날에 여호와께서 말씀하신 이 산지를 지금 내게 주소서 당신도 그 날에 들으셨거니와 그 곳에는 아낙 사람이 있고 그 성읍들은 크고 견고할지라도 여호와께서 나와 함께 하시면 내가 여호와께서 말씀하신 대로 그들을 쫓아내리이다 하니"],[13,"여호수아가 여분네의 아들 갈렙을 위하여 축복하고 헤브론을 그에게 주어 기업을 삼게 하매"],[14,"헤브론이 그니스 사람 여분네의 아들 갈렙의 기업이 되어 오늘까지 이르렀으니 이는 그가 이스라엘의 하나님 여호와께 충성하였음이라"],[15,"헤브론의 옛 이름은 기럇 아르바라 아르바는 아낙 사람 가운데에서 가장 큰 사람이었더라 그리고 그 땅에 전쟁이 그쳤더라"]],"24:16":[[7,"그 죽은 자로 말미암아 슬퍼하는 자와 떡을 떼며 위로하는 자가 없을 것이며 그들의 아버지나 어머니의 상사를 위하여 위로의 잔을 그들에게 마시게 할 자가 없으리라"],[9,"만군의 여호와 이스라엘의 하나님께서 이와 같이 말씀하시니라 보라 기뻐하는 소리와 즐거워하는 소리와 신랑의 소리와 신부의 소리를 내가 네 목전, 네 시대에 이 곳에서 끊어지게 하리라"]],"19:14":[[6,"너희가 가난한 자의 계획을 부끄럽게 하나 오직 여호와는 그의 피난처가 되시도다"]],"12:22":[[11,"왕이 율법책의 말을 듣자 곧 그의 옷을 찢으니라"],[12,"왕이 제사장 힐기야와 사반의 아들 아히감과 미가야의 아들 악볼과 서기관 사반과 왕의 시종 아사야에게 명령하여 이르되"],[13,"너희는 가서 나와 백성과 온 유다를 위하여 이 발견한 책의 말씀에 대하여 여호와께 물으라 우리 조상들이 이 책의 말씀을 듣지 아니하며 이 책에 우리를 위하여 기록된 모든 것을 행하지 아니하였으므로 여호와께서 우리에게 내리신 진노가 크도다"]],"10:23":[[10,"그가 나가서 손이 피곤하여 그의 손이 칼에 붙기까지 블레셋 사람을 치니라 그 날에 여호와께서 크게 이기게 하셨으므로 백성들은 돌아와 그의 뒤를 따라가며 노략할 뿐이었더라"]],"24:13":[[11,"여호와의 말씀이니라 띠가 사람의 허리에 속함 같이 내가 이스라엘 온 집과 유다 온 집으로 내게 속하게 하여 그들로 내 백성이 되게 하며 내 이름과 명예와 영광이 되게 하려 하였으나 그들이 듣지 아니하였느니라"]],"23:9":[[7,"그 정사와 평강의 더함이 무궁하며 또 다윗의 왕좌와 그의 나라에 군림하여 그 나라를 굳게 세우고 지금 이후로 영원히 정의와 공의로 그것을 보존하실 것이라 만군의 여호와의 열심이 이를 이루시리라"]],"12:11":[[4,"일곱째 해에 여호야다가 사람을 보내 가리 사람의 백부장들과 호위병의 백부장들을 불러 데리고 여호와의 성전으로 들어가서 그들과 언약을 맺고 그들에게 여호와의 성전에서 맹세하게 한 후에 왕자를 그들에게 보이고"],[5,"명령하여 이르되 너희가 행할 것이 이러하니 안식일에 들어온 너희 중 삼분의 일은 왕궁을 주의하여 지키고"]],"32:1":[[3,"그러나 요나가 여호와의 얼굴을 피하려고 일어나 다시스로 도망하려 하여 욥바로 내려갔더니 마침 다시스로 가는 배를 만난지라 여호와의 얼굴을 피하여 그들과 함께 다시스로 가려고 배삯을 주고 배에 올랐더라"]],"19:94":[[12,"여호와여 주로부터 징벌을 받으며 주의 법으로 교훈하심을 받는 자가 복이 있나니"]],"23:40":[[3,"외치는 자의 소리여 이르되 너희는 광야에서 여호와의 길을 예비하라 사막에서 우리 하나님의 대로를 평탄하게 하라"],[31,"오직 여호와를 앙망하는 자는 새 힘을 얻으리니 독수리가 날개치며 올라감 같을 것이요 달음박질하여도 곤비하지 아니하겠고 걸어가도 피곤하지 아니하리로다"]],"59:3":[[2,"우리가 다 실수가 많으니 만일 말에 실수가 없는 자라면 곧 온전한 사람이라 능히 온 몸도 굴레 씌우리라"],[15,"이러한 지혜는 위로부터 내려온 것이 아니요 땅 위의 것이요 정욕의 것이요 귀신의 것이니"],[18,"화평하게 하는 자들은 화평으로 심어 의의 열매를 거두느니라"]],"24:4":[[4,"유다인과 예루살렘 주민들아 너희는 스스로 할례를 행하여 너희 마음 가죽을 베고 나 여호와께 속하라 그리하지 아니하면 너희 악행으로 말미암아 나의 분노가 불 같이 일어나 사르리니 그것을 끌 자가 없으리라"]],"26:44":[[9,"주 여호와께서 이같이 말씀하셨느니라 이스라엘 족속 중에 있는 이방인 중에 마음과 몸에 할례를 받지 아니한 이방인은 내 성소에 들어오지 못하리라"]],"28:2":[[8,"곡식과 새 포도주와 기름은 내가 그에게 준 것이요 그들이 바알을 위하여 쓴 은과 금도 내가 그에게 더하여 준 것이거늘 그가 알지 못하도다"],[21,"여호와께서 이르시되 그 날에 내가 응답하리라 나는 하늘에 응답하고 하늘은 땅에 응답하고"]],"19:73":[[24,"주의 교훈으로 나를 인도하시고 후에는 영광으로 나를 영접하시리니"]],"6:11":[[3,"동쪽과 서쪽의 가나안 족속과 아모리 족속과 헷 족속과 브리스 족속과 산지의 여부스 족속과 미스바 땅 헤르몬 산 아래 히위 족속에게 사람을 보내매"]],"7:3":[[3,"블레셋의 다섯 군주들과 모든 가나안 족속과 시돈 족속과 바알 헤르몬 산에서부터 하맛 입구까지 레바논 산에 거주하는 히위 족속이라"]],"24:7":[[12,"너희는 내가 처음으로 내 이름을 둔 처소 실로에 가서 내 백성 이스라엘의 악에 대하여 내가 어떻게 행하였는지를 보라"],[31,"힌놈의 아들 골짜기에 도벳 사당을 건축하고 그들의 자녀들을 불에 살랐나니 내가 명령하지 아니하였고 내 마음에 생각하지도 아니한 일이니라"]],"18:37":[[22,"북쪽에서는 황금 같은 빛이 나오고 하나님께는 두려운 위엄이 있느니라"]],"9:9":[[6,"그가 대답하되 보소서 이 성읍에 하나님의 사람이 있는데 존경을 받는 사람이라 그가 말한 것은 반드시 다 응하나니 그리로 가사이다 그가 혹 우리가 갈 길을 가르쳐 줄까 하나이다 하는지라"],[9,"(옛적 이스라엘에 사람이 하나님께 가서 물으려 하면 말하기를 선견자에게로 가자 하였으니 지금 선지자라 하는 자를 옛적에는 선견자라 일컬었더라)"]],"24:23":[[32,"여호와의 말씀이니라 보라 거짓 꿈을 예언하여 이르며 거짓과 헛된 자만으로 내 백성을 미혹하게 하는 자를 내가 치리라 내가 그들을 보내지 아니하였으며 명령하지 아니하였나니 그들은 이 백성에게 아무 유익이 없느니라 여호와의 말씀이니라"]],"66:13":[[13,"큰 이적을 행하되 심지어 사람들 앞에서 불이 하늘로부터 땅에 내려오게 하고"],[14,"짐승 앞에서 받은 바 이적을 행함으로 땅에 거하는 자들을 미혹하며 땅에 거하는 자들에게 이르기를 칼에 상하였다가 살아난 짐승을 위하여 우상을 만들라 하더라"]],"52:2":[[4,"오직 하나님께 옳게 여기심을 입어 복음을 위탁 받았으니 우리가 이와 같이 말함은 사람을 기쁘게 하려 함이 아니요 오직 우리 마음을 감찰하시는 하나님을 기쁘시게 하려 함이라"]],"52:3":[[5,"이러므로 나도 참다 못하여 너희 믿음을 알기 위하여 그를 보내었노니 이는 혹 시험하는 자가 너희를 시험하여 우리 수고를 헛되게 할까 함이니"],[13,"너희 마음을 굳건하게 하시고 우리 주 예수께서 그의 모든 성도와 함께 강림하실 때에 하나님 우리 아버지 앞에서 거룩함에 흠이 없게 하시기를 원하노라"]],"38:4":[[6,"그가 내게 대답하여 이르되 여호와께서 스룹바벨에게 하신 말씀이 이러하니라 만군의 여호와께서 말씀하시되 이는 힘으로 되지 아니하며 능력으로 되지 아니하고 오직 나의 영으로 되느니라"]],"19:10":[[1,"여호와여 어찌하여 멀리 서시며 어찌하여 환난 때에 숨으시나이까"],[2,"악한 자가 교만하여 가련한 자를 심히 압박하오니 그들이 자기가 베푼 꾀에 빠지게 하소서"],[3,"악인은 그의 마음의 욕심을 자랑하며 탐욕을 부리는 자는 여호와를 배반하여 멸시하나이다"],[4,"악인은 그의 교만한 얼굴로 말하기를 여호와께서 이를 감찰하지 아니하신다 하며 그의 모든 사상에 하나님이 없다 하나이다"],[5,"그의 길은 언제든지 견고하고 주의 심판은 높아서 그에게 미치지 못하오니 그는 그의 모든 대적들을 멸시하며"],[6,"그의 마음에 이르기를 나는 흔들리지 아니하며 대대로 환난을 당하지 아니하리라 하나이다"],[7,"그의 입에는 저주와 거짓과 포악이 충만하며 그의 혀 밑에는 잔해와 죄악이 있나이다"],[8,"그가 마을 구석진 곳에 앉으며 그 은밀한 곳에서 무죄한 자를 죽이며 그의 눈은 가련한 자를 엿보나이다"],[9,"사자가 자기의 굴에 엎드림 같이 그가 은밀한 곳에 엎드려 가련한 자를 잡으려고 기다리며 자기 그물을 끌어당겨 가련한 자를 잡나이다"],[10,"그가 구푸려 엎드리니 그의 포악으로 말미암아 가련한 자들이 넘어지나이다"],[11,"그가 그의 마음에 이르기를 하나님이 잊으셨고 그의 얼굴을 가리셨으니 영원히 보지 아니하시리라 하나이다"],[12,"여호와여 일어나옵소서 하나님이여 손을 드옵소서 가난한 자들을 잊지 마옵소서"],[13,"어찌하여 악인이 하나님을 멸시하여 그의 마음에 이르기를 주는 감찰하지 아니하리라 하나이까"],[14,"주께서는 보셨나이다 주는 재앙과 원한을 감찰하시고 주의 손으로 갚으려 하시오니 외로운 자가 주를 의지하나이다 주는 벌써부터 고아를 도우시는 이시니이다"],[15,"악인의 팔을 꺾으소서 악한 자의 악을 더 이상 찾아낼 수 없을 때까지 찾으소서"],[16,"여호와께서는 영원무궁하도록 왕이시니 이방 나라들이 주의 땅에서 멸망하였나이다"],[17,"여호와여 주는 겸손한 자의 소원을 들으셨사오니 그들의 마음을 준비하시며 귀를 기울여 들으시고"],[18,"고아와 압제 당하는 자를 위하여 심판하사 세상에 속한 자가 다시는 위협하지 못하게 하시리이다"]],"28:14":[[3,"우리가 앗수르의 구원을 의지하지 아니하며 말을 타지 아니하며 다시는 우리의 손으로 만든 것을 향하여 너희는 우리의 신이라 하지 아니하오리니 이는 고아가 주로 말미암아 긍휼을 얻음이니이다 할지니라"]],"10:20":[[19,"나는 이스라엘의 화평하고 충성된 자 중 하나이거늘 당신이 이스라엘 가운데 어머니 같은 성을 멸하고자 하시는도다 어찌하여 당신이 여호와의 기업을 삼키고자 하시나이까 하니"]],"30:8":[[11,"주 여호와의 말씀이니라 보라 날이 이를지라 내가 기근을 땅에 보내리니 양식이 없어 주림이 아니며 물이 없어 갈함이 아니요 여호와의 말씀을 듣지 못한 기갈이라"]],"19:112":[[1,"할렐루야, 여호와를 경외하며 그의 계명을 크게 즐거워하는 자는 복이 있도다"]],"18:5":[[15,"하나님은 가난한 자를 강한 자의 칼과 그 입에서, 또한 그들의 손에서 구출하여 주시나니"]],"30:4":[[5,"누룩 넣은 것을 불살라 수은제로 드리며 낙헌제를 소리내어 선포하려무나 이스라엘 자손들아 이것이 너희가 기뻐하는 바니라 주 여호와의 말씀이니라"]],"41:8":[[15,"예수께서 경고하여 이르시되 삼가 바리새인들의 누룩과 헤롯의 누룩을 주의하라 하시니"]],"23:3":[[10,"너희는 의인에게 복이 있으리라 말하라 그들은 그들의 행위의 열매를 먹을 것임이요"]],"28:10":[[12,"너희가 자기를 위하여 공의를 심고 인애를 거두라 너희 묵은 땅을 기경하라 지금이 곧 여호와를 찾을 때니 마침내 여호와께서 오사 공의를 비처럼 너희에게 내리시리라"]],"9:8":[[1,"사무엘이 늙으매 그의 아들들을 이스라엘 사사로 삼으니"],[2,"장자의 이름은 요엘이요 차자의 이름은 아비야라 그들이 브엘세바에서 사사가 되니라"],[3,"그의 아들들이 자기 아버지의 행위를 따르지 아니하고 이익을 따라 뇌물을 받고 판결을 굽게 하니라"],[11,"이르되 너희를 다스릴 왕의 제도는 이러하니라 그가 너희 아들들을 데려다가 그의 병거와 말을 어거하게 하리니 그들이 그 병거 앞에서 달릴 것이며"],[12,"그가 또 너희의 아들들을 천부장과 오십부장을 삼을 것이며 자기 밭을 갈게 하고 자기 추수를 하게 할 것이며 자기 무기와 병거의 장비도 만들게 할 것이며"],[13,"그가 또 너희의 딸들을 데려다가 향료 만드는 자와 요리하는 자와 떡 굽는 자로 삼을 것이며"],[14,"그가 또 너희의 밭과 포도원과 감람원에서 제일 좋은 것을 가져다가 자기의 신하들에게 줄 것이며"],[15,"그가 또 너희의 곡식과 포도원 소산의 십일조를 거두어 자기의 관리와 신하에게 줄 것이며"],[16,"그가 또 너희의 노비와 가장 아름다운 소년과 나귀들을 끌어다가 자기 일을 시킬 것이며"],[17,"너희의 양 떼의 십분의 일을 거두어 가리니 너희가 그의 종이 될 것이라"]],"10:21":[[1,"다윗의 시대에 해를 거듭하여 삼 년 기근이 있으므로 다윗이 여호와 앞에 간구하매 여호와께서 이르시되 이는 사울과 피를 흘린 그의 집으로 말미암음이니 그가 기브온 사람을 죽였음이니라 하시니라"],[6,"자손 일곱 사람을 우리에게 내주소서 여호와께서 택하신 사울의 고을 기브아에서 우리가 그들을 여호와 앞에서 목 매어 달겠나이다 하니 왕이 이르되 내가 내주리라 하니라"]],"7:15":[[14,"삼손이 레히에 이르매 블레셋 사람들이 그에게로 마주 나가며 소리 지를 때 여호와의 영이 삼손에게 갑자기 임하시매 그의 팔 위의 밧줄이 불탄 삼과 같이 그의 결박되었던 손에서 떨어진지라"]],"23:13":[[7,"그러므로 모든 손의 힘이 풀리고 각 사람의 마음이 녹을 것이라"]],"26:21":[[7,"그들이 네게 묻기를 네가 어찌하여 탄식하느냐 하거든 대답하기를 재앙이 다가온다는 소문 때문이니 각 마음이 녹으며 모든 손이 약하여지며 각 영이 쇠하며 모든 무릎이 물과 같이 약해지리라 보라 재앙이 오나니 반드시 이루어지리라 주 여호와의 말씀이니라 하라"]],"23:8":[[5,"여호와께서 다시 내게 말씀하여 이르시되"],[6,"이 백성이 천천히 흐르는 실로아 물을 버리고 르신과 르말리야의 아들을 기뻐하느니라"],[7,"그러므로 주 내가 흉용하고 창일한 큰 하수 곧 앗수르 왕과 그의 모든 위력으로 그들을 뒤덮을 것이라 그 모든 골짜기에 차고 모든 언덕에 넘쳐"],[8,"흘러 유다에 들어와서 가득하여 목에까지 미치리라 임마누엘이여 그가 펴는 날개가 네 땅에 가득하리라 하셨느니라"]],"23:22":[[13,"너희가 기뻐하며 즐거워하여 소를 죽이고 양을 잡아 고기를 먹고 포도주를 마시면서 내일 죽으리니 먹고 마시자 하는도다"]],"6:6":[[18,"너희는 온전히 바치고 그 바친 것 중에서 어떤 것이든지 취하여 너희가 이스라엘 진영으로 바치는 것이 되게 하여 고통을 당하게 되지 아니하도록 오직 너희는 그 바친 물건에 손대지 말라"]],"23:56":[[3,"여호와께 연합한 이방인은 말하기를 여호와께서 나를 그의 백성 중에서 반드시 갈라내시리라 말하지 말며 고자도 말하기를 나는 마른 나무라 하지 말라"],[4,"여호와께서 이와 같이 말씀하시기를 나의 안식일을 지키며 내가 기뻐하는 일을 선택하며 나의 언약을 굳게 잡는 고자들에게는"],[5,"내가 내 집에서, 내 성 안에서 아들이나 딸보다 나은 기념물과 이름을 그들에게 주며 영원한 이름을 주어 끊어지지 아니하게 할 것이며"],[6,"또 여호와와 연합하여 그를 섬기며 여호와의 이름을 사랑하며 그의 종이 되며 안식일을 지켜 더럽히지 아니하며 나의 언약을 굳게 지키는 이방인마다"],[7,"내가 곧 그들을 나의 성산으로 인도하여 기도하는 내 집에서 그들을 기쁘게 할 것이며 그들의 번제와 희생을 나의 제단에서 기꺼이 받게 되리니 이는 내 집은 만민이 기도하는 집이라 일컬음이 될 것임이라"],[8,"이스라엘의 쫓겨난 자를 모으시는 주 여호와가 말하노니 내가 이미 모은 백성 외에 또 모아 그에게 속하게 하리라 하셨느니라"]],"8:1":[[16,"룻이 이르되 내게 어머니를 떠나며 어머니를 따르지 말고 돌아가라 강권하지 마옵소서 어머니께서 가시는 곳에 나도 가고 어머니께서 머무시는 곳에서 나도 머물겠나이다 어머니의 백성이 나의 백성이 되고 어머니의 하나님이 나의 하나님이 되시리니"]],"11:2":[[13,"학깃의 아들 아도니야가 솔로몬의 어머니 밧세바에게 나아온지라 밧세바가 이르되 네가 화평한 목적으로 왔느냐 대답하되 화평한 목적이니이다"],[14,"또 이르되 내가 말씀드릴 일이 있나이다 밧세바가 이르되 말하라"],[15,"그가 이르되 당신도 아시는 바이거니와 이 왕위는 내 것이었고 온 이스라엘은 다 얼굴을 내게로 향하여 왕으로 삼으려 하였는데 그 왕권이 돌아가 내 아우의 것이 되었음은 여호와께로 말미암음이니이다"],[16,"이제 내가 한 가지 소원을 당신에게 구하오니 내 청을 거절하지 마옵소서 밧세바가 이르되 말하라"],[17,"그가 이르되 청하건대 솔로몬 왕에게 말씀하여 그가 수넴 여자 아비삭을 내게 주어 아내를 삼게 하소서 왕이 당신의 청을 거절하지 아니하리이다"],[18,"밧세바가 이르되 좋다 내가 너를 위하여 왕께 말하리라"],[19,"밧세바가 이에 아도니야를 위하여 말하려고 솔로몬 왕에게 이르니 왕이 일어나 영접하여 절한 후에 다시 왕좌에 앉고 그의 어머니를 위하여 자리를 베푸니 그가 그의 오른쪽에 앉는지라"],[20,"밧세바가 이르되 내가 한 가지 작은 일로 왕께 구하오니 내 청을 거절하지 마소서 왕이 대답하되 내 어머니여 구하소서 내가 어머니의 청을 거절하지 아니하리이다"],[21,"이르되 청하건대 수넴 여자 아비삭을 아도니야에게 주어 아내로 삼게 하소서"],[22,"솔로몬 왕이 그의 어머니에게 대답하여 이르되 어찌하여 아도니야를 위하여 수넴 여자 아비삭을 구하시나이까 그는 나의 형이오니 그를 위하여 왕권도 구하옵소서 그뿐 아니라 제사장 아비아달과 스루야의 아들 요압을 위해서도 구하옵소서 하고"],[23,"여호와를 두고 맹세하여 이르되 아도니야가 이런 말을 하였은즉 그의 생명을 잃지 아니하면 하나님은 내게 벌 위에 벌을 내리심이 마땅하니이다"],[24,"그러므로 이제 나를 세워 내 아버지 다윗의 왕위에 오르게 하시고 허락하신 말씀대로 나를 위하여 집을 세우신 여호와께서 살아 계심을 두고 맹세하노니 아도니야는 오늘 죽임을 당하리라 하고"],[25,"여호야다의 아들 브나야를 보내매 그가 아도니야를 쳐서 죽였더라"]],"15:9":[[1,"이 일 후에 방백들이 내게 나아와 이르되 이스라엘 백성과 제사장들과 레위 사람들이 이 땅 백성들에게서 떠나지 아니하고 가나안 사람들과 헷 사람들과 브리스 사람들과 여부스 사람들과 암몬 사람들과 모압 사람들과 애굽 사람들과 아모리 사람들의 가증한 일을 행하여"],[2,"그들의 딸을 맞이하여 아내와 며느리로 삼아 거룩한 자손이 그 지방 사람들과 서로 섞이게 하는데 방백들과 고관들이 이 죄에 더욱 으뜸이 되었다 하는지라"],[3,"내가 이 일을 듣고 속옷과 겉옷을 찢고 머리털과 수염을 뜯으며 기가 막혀 앉으니"],[4,"이에 이스라엘의 하나님의 말씀으로 말미암아 떠는 자가 사로잡혔던 이 사람들의 죄 때문에 다 내게로 모여오더라 내가 저녁 제사 드릴 때까지 기가 막혀 앉았더니"],[5,"저녁 제사를 드릴 때에 내가 근심 중에 일어나서 속옷과 겉옷을 찢은 채 무릎을 꿇고 나의 하나님 여호와를 향하여 손을 들고"],[6,"말하기를 나의 하나님이여 내가 부끄럽고 낯이 뜨거워서 감히 나의 하나님을 향하여 얼굴을 들지 못하오니 이는 우리 죄악이 많아 정수리에 넘치고 우리 허물이 커서 하늘에 미침이니이다"],[7,"우리 조상들의 때로부터 오늘까지 우리의 죄가 심하매 우리의 죄악으로 말미암아 우리와 우리 왕들과 우리 제사장들을 여러 나라 왕들의 손에 넘기사 칼에 죽으며 사로잡히며 노략을 당하며 얼굴을 부끄럽게 하심이 오늘날과 같으니이다"],[8,"이제 우리 하나님 여호와께서 우리에게 잠시 동안 은혜를 베푸사 얼마를 남겨 두어 피하게 하신 우리를 그 거룩한 처소에 박힌 못과 같게 하시고 우리 하나님이 우리 눈을 밝히사 우리가 종노릇 하는 중에서 조금 소생하게 하셨나이다"],[9,"우리가 비록 노예가 되었사오나 우리 하나님이 우리를 그 종살이하는 중에 버려 두지 아니하시고 바사 왕들 앞에서 우리가 불쌍히 여김을 입고 소생하여 우리 하나님의 성전을 세우게 하시며 그 무너진 것을 수리하게 하시며 유다와 예루살렘에서 우리에게 울타리를 주셨나이다"],[10,"우리 하나님이여 이렇게 하신 후에도 우리가 주의 계명을 저버렸사오니 이제 무슨 말씀을 하오리이까"]],"20:13":[[9,"의인의 빛은 환하게 빛나고 악인의 등불은 꺼지느니라"]],"23:60":[[21,"네 백성이 다 의롭게 되어 영원히 땅을 차지하리니 그들은 내가 심은 가지요 내가 손으로 만든 것으로서 나의 영광을 나타낼 것인즉"]],"24:21":[[12,"여호와께서 이와 같이 말씀하시니라 다윗의 집이여 너는 아침마다 정의롭게 판결하여 탈취 당한 자를 압박자의 손에서 건지라 그리하지 아니하면 너희의 악행 때문에 내 분노가 불 같이 일어나서 사르리니 능히 끌 자가 없으리라"]],"19:85":[[4,"우리 구원의 하나님이여 우리를 돌이키시고 우리에게 향하신 주의 분노를 거두소서"],[9,"진실로 그의 구원이 그를 경외하는 자에게 가까우니 영광이 우리 땅에 머무르리이다"]],"24:36":[[23,"여후디가 서너 쪽을 낭독하면 왕이 면도칼로 그것을 연하여 베어 화로 불에 던져서 두루마리를 모두 태웠더라"]],"24:10":[[23,"여호와여 내가 알거니와 사람의 길이 자신에게 있지 아니하니 걸음을 지도함이 걷는 자에게 있지 아니하니이다"]],"14:25":[[10,"아마샤가 이에 에브라임에서 자기에게 온 군대를 나누어 그들의 고향으로 돌아가게 하였더니 그 무리가 유다 사람에게 심히 노하여 분연히 고향으로 돌아갔더라"]],"19:43":[[1,"하나님이여 나를 판단하시되 경건하지 아니한 나라에 대하여 내 송사를 변호하시며 간사하고 불의한 자에게서 나를 건지소서"]],"18:9":[[30,"내가 눈 녹은 물로 몸을 씻고 잿물로 손을 깨끗하게 할지라도"]],"23:51":[[18,"네가 낳은 모든 아들 중에 너를 인도할 자가 없고 네가 양육한 모든 아들 중에 그 손으로 너를 이끌 자도 없도다"],[20,"네 아들들이 곤비하여 그물에 걸린 영양 같이 온 거리 모퉁이에 누웠으니 그들에게 여호와의 분노와 네 하나님의 견책이 가득하도다"]],"28:1":[[1,"웃시야와 요담과 아하스와 히스기야가 이어 유다 왕이 된 시대 곧 요아스의 아들 여로보암이 이스라엘 왕이 된 시대에 브에리의 아들 호세아에게 임한 여호와의 말씀이라"]],"12:4":[[7,"그 여인이 하나님의 사람에게 나아가서 말하니 그가 이르되 너는 가서 기름을 팔아 빚을 갚고 남은 것으로 너와 네 두 아들이 생활하라 하였더라"]],"19:90":[[10,"우리의 연수가 칠십이요 강건하면 팔십이라도 그 연수의 자랑은 수고와 슬픔뿐이요 신속히 가니 우리가 날아가나이다"]]};